-- 로컬(local) 프로파일 참고용 추가 시드: DB 카테고리 1회차 — 객관식 25문항 + 서술형 50문항 = 총 75문항.
-- docs/TAG.md(태그 사전) + docs/SCRIPT.md(객관식) + docs/SCRIPT_ESSAY.md(서술형) 규칙으로 생성했다.
--
-- 생성 방식: 태그 사전을 먼저 확정하고 태그를 축으로 문항을 만들었다.
--   객관식(MULTIPLE_CHOICE, 25개): 태그 25개를 5개 클러스터 × 5개로 나누고,
--     클러스터 1개 = 그룹 1개(본질문 1 + 그 보기 4개에 연결된 꼬리질문 4개) = 5문항.
--     태그 25개와 문항 25개가 1:1이며, 각 태그가 정확히 1회씩 주 태그로 쓰였다.
--     "본질문"·"꼬리질문"은 생성 순서를 가리키는 표현일 뿐 도메인/DB에는 엔티티 차원의 구분이 없다 —
--     모든 question 행은 동등한 독립 문항이며 문제은행에 노출된다.
--     본질문의 보기 K는 @qN_K로, 꼬리질문의 보기 4개는 전부 부모 @qN으로 되돌아가는 순환 연결이다.
--     따라서 answer_choice.related_question_id에 NULL이 하나도 없다.
--     정답 보기의 위치(sequence)는 문항마다 1~4로 무작위 분산되어 있다.
--   서술형(ESSAY, 50개): 같은 태그 25개에 대해 태그당 2문항. 두 문항은 같은 태그의 서로 다른 측면을 묻는다.
--     서술형은 본 질문만 저장하며(꼬리질문은 풀이 세션마다 AI가 동적 생성) answer_choice가 없다.
--     ※ SCRIPT_ESSAY.md의 "회차 내 주 태그 중복 금지" 규칙에 대한 의도된 예외다(태그당 2문항 요청).
--
-- [태그 정규화] question_tag는 태그 이름이 아니라 tag 테이블의 id를 참조한다.
--   따라서 이 파일보다 먼저 data-tag.sql(사전 238개)이 로드돼야 한다.
--   태그 부여는 (@qN, (SELECT id FROM tag WHERE name = '...')) 형태이며, 이 파일이 쓰는 태그 206종은
--   전부 docs/TAG.md 사전 안에 있으므로 서브셀렉트가 NULL이 되는 행은 없다.
--
-- id는 AUTO_INCREMENT이며, 문항 간 연결과 태그 부여는 세션 변수(@qN, @qN_K, @eN)로 캡처한 실제 id를 쓴다.
-- 대입은 = 를 쓴다(H2 MySQL 호환모드에서 := 는 문법 오류).
--
-- 기본 설정으로는 자동 로드되지 않는다. 적용하려면 application-db-local.yml의
-- spring.sql.init.data-locations에 classpath:data3.sql을 추가한다.

-- 테스트 유저 (email: test@test.test / password: test) — data2.sql과 중복이라 주석 처리해 둔다.
-- INSERT INTO users (email, password, nickname, position, daily_goal) VALUES
-- ('test@test.test', '$2a$10$QnOWMKP6UpzZHYzphdiuaOyg.Ei2ihHclJ1r5YmU0WYsvxQxSi/8q', 'test', 'BACKEND', 10);

-- ============================================================
-- [태그 사전] DB (docs/TAG.md 기준, 카테고리 전체 31개)
-- [회차] 1회차 — 25개 소비 / 이월 6개(SQL 기본 문법, 파티셔닝, 복제와 샤딩, 뷰, 페이지네이션, 슬로우 쿼리)
-- [이번 회차 주 태그 25개]
-- 인덱스 / 복합 인덱스 / 커버링 인덱스 / 클러스터드 인덱스 / 실행 계획
-- / 트랜잭션 / ACID / 격리 수준 / 동시성 이상 현상 / MVCC
-- / 락 / 낙관적 락과 비관적 락 / 트랜잭션 데드락 / 트랜잭션 전파 / 커넥션 풀
-- / 정규화 / 반정규화 / 키와 제약조건 / NULL 처리 / RDB와 NoSQL
-- / 조인 / 서브쿼리 / 집계와 GROUP BY / ORM과 영속성 컨텍스트 / N+1 문제
-- [클러스터 → 주 태그 배정]
-- q1(인덱스와 실행 계획) : q1=인덱스  q1_1=복합 인덱스  q1_2=커버링 인덱스  q1_3=클러스터드 인덱스  q1_4=실행 계획
-- q2(트랜잭션과 격리)    : q2=트랜잭션  q2_1=ACID  q2_2=격리 수준  q2_3=동시성 이상 현상  q2_4=MVCC
-- q3(락과 동시성 제어)   : q3=락  q3_1=낙관적 락과 비관적 락  q3_2=트랜잭션 데드락  q3_3=트랜잭션 전파  q3_4=커넥션 풀
-- q4(스키마 설계)        : q4=정규화  q4_1=반정규화  q4_2=키와 제약조건  q4_3=NULL 처리  q4_4=RDB와 NoSQL
-- q5(조인과 ORM)         : q5=조인  q5_1=서브쿼리  q5_2=집계와 GROUP BY  q5_3=ORM과 영속성 컨텍스트  q5_4=N+1 문제
-- ============================================================


-- ============================================================
-- 객관식 (MULTIPLE_CHOICE) — 25문항
-- ============================================================

-- ------------------------------------------------------------
-- 그룹 q1 · 클러스터: 인덱스와 실행 계획
-- ------------------------------------------------------------
-- 본질문 q1 [주 태그: 인덱스]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('인덱스를 추가할 때의 트레이드오프', '테이블에 인덱스를 추가할 때 생기는 트레이드오프를 가장 정확하게 설명한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '인덱스는 컬럼 값을 정렬해 담은 별도의 자료구조이므로 조회 시 전체 테이블을 훑지 않고 원하는 행으로 바로 찾아갈 수 있다. 그 대가로 INSERT·UPDATE·DELETE가 일어날 때마다 인덱스도 함께 갱신해야 하고, 인덱스 자체를 저장할 공간도 추가로 필요하다. 즉 읽기 성능을 쓰기 비용과 저장 공간으로 사는 구조다.');
SET @q1 = LAST_INSERT_ID();

-- 꼬리질문 q1_1 (q1의 1번 보기) [주 태그: 복합 인덱스]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('복합 인덱스와 컬럼 순서', '컬럼 (a, b, c) 순서로 만든 복합 인덱스를 효율적으로 활용할 수 있는 조건은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '복합 인덱스는 선행 컬럼을 기준으로 먼저 정렬하고 그 안에서 다음 컬럼을 정렬한 구조다. 따라서 선행 컬럼 a가 조건에 있어야 탐색의 출발점이 생기고, a부터 순서대로 이어지는 조건일 때 인덱스를 가장 잘 활용한다. 선행 컬럼을 빼거나 컬럼에 함수를 씌우면 정렬 순서를 이용할 수 없다.');
SET @q1_1 = LAST_INSERT_ID();

-- 꼬리질문 q1_2 (q1의 2번 보기) [주 태그: 커버링 인덱스]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('인덱스만 읽고 끝나는 조회', '조회에 필요한 컬럼을 인덱스가 모두 담고 있어 테이블 데이터에 접근하지 않고 처리되는 상황을 설명한 것으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 'SELECT 목록과 WHERE 조건에 쓰이는 컬럼이 모두 인덱스에 포함되어 있으면 인덱스만 읽고 결과를 만들 수 있다. 이 경우 인덱스에서 행 위치를 얻어 테이블을 한 번 더 읽는 단계가 사라지므로 조회가 크게 빨라진다.');
SET @q1_2 = LAST_INSERT_ID();

-- 꼬리질문 q1_3 (q1의 3번 보기) [주 태그: 클러스터드 인덱스]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('클러스터드 인덱스가 보조 인덱스와 다른 점', '클러스터드 인덱스가 보조 인덱스와 구별되는 핵심 특징으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '클러스터드 인덱스는 인덱스 키 순서대로 실제 데이터 행을 저장한다. 데이터의 물리적 배치 자체가 인덱스이므로 테이블당 하나만 존재할 수 있다. 반면 보조 인덱스는 키와 행을 찾아갈 정보만 담은 별도 구조라 여러 개를 만들 수 있다.');
SET @q1_3 = LAST_INSERT_ID();

-- 꼬리질문 q1_4 (q1의 4번 보기) [주 태그: 실행 계획]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('쿼리 튜닝에서 실행 계획을 먼저 보는 이유', '쿼리를 손대기 전에 실행 계획(Execution Plan)을 먼저 확인하는 이유로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '실행 계획은 옵티마이저가 실제로 선택한 접근 방법을 보여준다. 인덱스를 탔는지 풀 스캔을 했는지, 조인 순서와 방식이 무엇인지, 예상 처리 행 수가 얼마인지가 드러난다. 비용이 어디서 발생하는지 근거를 확인한 뒤 손대야 감으로 고치는 헛된 튜닝을 피할 수 있다.');
SET @q1_4 = LAST_INSERT_ID();

-- 본질문(q1) 선택지: 4개 보기 전부가 꼬리질문에 연결됨 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q1, '여러 컬럼을 하나로 묶어 인덱스를 만들면 조건에 쓰는 컬럼 순서와 상관없이 항상 같은 효율로 쓸 수 있다.', 1, FALSE, '트레이드오프에 대한 설명이 아니며 내용도 틀렸다. 복합 인덱스는 선언한 컬럼 순서대로 정렬되어 있어서, 선행 컬럼이 조건에서 빠지면 인덱스를 제대로 활용할 수 없다.', @q1_1),
(@q1, '조회 속도는 빨라지지만 쓰기 작업마다 인덱스를 함께 갱신해야 하고 저장 공간도 추가로 든다.', 2, TRUE, '', @q1_2),
(@q1, '인덱스를 추가하면 테이블의 실제 저장 순서가 항상 그 인덱스 기준으로 재배치된다.', 3, FALSE, '저장 순서를 결정하는 것은 클러스터드 인덱스 하나뿐이다. 그 밖의 보조 인덱스는 별도 구조에 키와 행 위치 정보만 담고 테이블의 물리적 순서는 바꾸지 않는다.', @q1_3),
(@q1, '인덱스를 만들어 두면 옵티마이저가 항상 그 인덱스를 쓰므로 조회 성능이 보장된다.', 4, FALSE, '옵티마이저는 통계와 예상 비용을 근거로 인덱스를 쓸지 말지 판단한다. 조건에 해당하는 범위가 너무 넓거나 컬럼에 함수가 씌워지면 인덱스를 무시하고 풀 스캔을 고를 수 있다.', @q1_4);

-- 꼬리질문(q1_1) 선택지: 전부 부모 @q1으로 되돌아가는 순환 연결 (정답 sequence = 3)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q1_1, 'WHERE b = ? AND c = ? 처럼 선행 컬럼 a를 빼고 뒤쪽 컬럼만 조건에 사용한 경우', 1, FALSE, '복합 인덱스는 a로 먼저 정렬된 구조이므로 a가 조건에 없으면 탐색을 시작할 지점이 없다. 결국 인덱스 전체를 훑거나 아예 타지 못한다.', @q1),
(@q1_1, 'WHERE c LIKE ''%값'' 처럼 마지막 컬럼에 앞부분이 열린 LIKE 조건만 준 경우', 2, FALSE, '선행 컬럼이 빠진 것도 문제이고, 앞부분이 와일드카드로 열린 LIKE는 정렬 순서를 이용할 수 없어 인덱스 탐색에 쓸 수 없다.', @q1),
(@q1_1, 'WHERE a = ? AND b = ? 처럼 선행 컬럼부터 순서대로 이어서 조건에 사용한 경우', 3, TRUE, '', @q1),
(@q1_1, 'a, b, c 세 컬럼을 모두 조건에 쓰되 각 컬럼에 함수를 씌워 비교한 경우', 4, FALSE, '컬럼에 함수를 적용하면 저장된 원래 값의 정렬 순서를 쓸 수 없다. 세 컬럼을 모두 조건에 넣어도 인덱스를 타지 못한다.', @q1);

-- 꼬리질문(q1_2) 선택지: 전부 부모 @q1으로 되돌아가는 순환 연결 (정답 sequence = 1)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q1_2, '조회에 필요한 컬럼이 모두 인덱스에 있어 인덱스만 읽고 결과를 반환하는 상태다.', 1, TRUE, '', @q1),
(@q1_2, '인덱스에서 행 위치를 찾은 뒤 반드시 테이블에서 나머지 컬럼을 한 번 더 읽는 상태다.', 2, FALSE, '이것은 인덱스를 탔을 때의 일반적인 동작이다. 질문이 가리키는 것은 그 추가 접근이 아예 필요 없는 경우다.', @q1),
(@q1_2, '인덱스를 메모리에 전부 올려 두어 디스크 접근이 사라진 상태다.', 3, FALSE, '버퍼 풀에 캐시된 상황과 혼동한 설명이다. 캐시 여부와 무관하게, 인덱스가 필요한 컬럼을 다 담고 있는지가 핵심이다.', @q1),
(@q1_2, '테이블 전체를 스캔하되 결과만 인덱스 순서대로 정렬해 반환하는 상태다.', 4, FALSE, '테이블 전체를 읽는다면 인덱스만으로 처리한 것이 아니다. 정렬 순서를 맞춘다고 테이블 접근이 사라지지는 않는다.', @q1);

-- 꼬리질문(q1_3) 선택지: 전부 부모 @q1으로 되돌아가는 순환 연결 (정답 sequence = 4)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q1_3, '조회 패턴마다 하나씩 둘 수 있어 테이블에 여러 개를 만들 수 있다.', 1, FALSE, '여러 개를 만들 수 있는 것은 보조 인덱스다. 클러스터드 인덱스는 데이터의 물리적 저장 순서 자체이므로 테이블당 하나만 존재할 수 있다.', @q1),
(@q1_3, '데이터를 정렬하지 않고 삽입된 순서 그대로 저장한다.', 2, FALSE, '삽입 순서대로 쌓아 두는 것은 인덱스가 없는 힙 구조의 특징이다. 클러스터드 인덱스는 키 순서를 유지하며 저장한다.', @q1),
(@q1_3, '인덱스 키만 저장하고 실제 데이터 행을 찾아갈 정보는 담지 않는다.', 3, FALSE, '키만 있고 행을 찾아갈 수 없다면 인덱스로 쓸 수 없다. 클러스터드 인덱스는 리프에 데이터 행 자체를 담고 있다.', @q1),
(@q1_3, '인덱스 키 순서대로 실제 데이터 행이 저장되므로 테이블당 하나만 둘 수 있다.', 4, TRUE, '', @q1);

-- 꼬리질문(q1_4) 선택지: 전부 부모 @q1으로 되돌아가는 순환 연결 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q1_4, '실행 계획에 표시된 예상 비용은 실제 실행 시간과 항상 일치하므로 측정을 대신할 수 있다.', 1, FALSE, '예상 비용은 통계를 근거로 계산한 추정치다. 통계가 낡았거나 데이터 분포가 치우쳐 있으면 실제 소요 시간과 크게 어긋날 수 있어 측정을 대체하지 못한다.', @q1),
(@q1_4, '옵티마이저가 인덱스를 탔는지, 조인 순서와 방식이 무엇인지 근거를 확인할 수 있다.', 2, TRUE, '', @q1),
(@q1_4, '실행 계획을 직접 수정하면 쿼리문을 바꾸지 않고도 결과 집합을 다르게 만들 수 있다.', 3, FALSE, '실행 계획은 같은 결과를 어떤 방법으로 얻을지에 대한 것이다. 접근 방법을 바꿔도 반환되는 결과 집합은 달라지지 않는다.', @q1),
(@q1_4, '문법 오류를 찾아주는 도구이므로 쿼리가 올바른지 검증하는 데 쓴다.', 4, FALSE, '문법 오류는 실행 계획을 뽑기 전 파싱 단계에서 걸러진다. 실행 계획은 문법이 아니라 성능을 판단하기 위한 정보다.', @q1);

-- ------------------------------------------------------------
-- 그룹 q2 · 클러스터: 트랜잭션과 격리 수준
-- ------------------------------------------------------------
-- 본질문 q2 [주 태그: 트랜잭션]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('트랜잭션을 하나의 단위로 묶는 이유', '여러 개의 SQL을 하나의 트랜잭션으로 묶는 근본적인 이유로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '트랜잭션은 여러 작업을 논리적으로 나눌 수 없는 하나의 단위로 만든다. 계좌 이체처럼 출금과 입금이 함께 성공하거나 함께 실패해야 하는 작업에서, 중간에 실패하면 이미 반영한 변경을 되돌려 데이터가 어중간한 상태로 남지 않게 한다. 성능을 위한 장치가 아니라 데이터 일관성을 지키기 위한 장치다.');
SET @q2 = LAST_INSERT_ID();

-- 꼬리질문 q2_1 (q2의 1번 보기) [주 태그: ACID]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('ACID의 지속성이 보장하는 것', '트랜잭션의 ACID 속성 중 지속성(Durability)이 보장하는 내용으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '지속성은 커밋이 끝난 트랜잭션의 결과가 이후 시스템이 비정상 종료되더라도 보존된다는 보장이다. DBMS는 변경 내용을 로그에 먼저 안전하게 기록한 뒤 커밋을 알리고, 장애가 나면 재시작 시 그 로그로 결과를 복원한다.');
SET @q2_1 = LAST_INSERT_ID();

-- 꼬리질문 q2_2 (q2의 2번 보기) [주 태그: 격리 수준]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('격리 수준을 낮출 때 얻는 것과 잃는 것', '트랜잭션 격리 수준을 READ COMMITTED에서 READ UNCOMMITTED로 낮출 때 나타나는 변화로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '격리 수준을 낮추면 트랜잭션이 서로를 덜 막으므로 동시 처리량은 늘어나지만, 그만큼 허용되는 이상 현상이 많아진다. READ UNCOMMITTED는 아직 커밋되지 않은 변경까지 읽을 수 있어 더티 리드가 발생한다. 즉 동시성과 정확성을 맞바꾸는 선택이다.');
SET @q2_2 = LAST_INSERT_ID();

-- 꼬리질문 q2_3 (q2의 3번 보기) [주 태그: 동시성 이상 현상]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('반복 불가능한 읽기가 일어나는 상황', '한 트랜잭션 안에서 같은 행을 두 번 조회했는데 값이 달라지는 이상 현상에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '반복 불가능한 읽기(Non-Repeatable Read)는 한 트랜잭션이 같은 행을 다시 읽는 사이에 다른 트랜잭션이 그 행을 수정하고 커밋해 값이 달라지는 현상이다. 같은 조건의 조회 결과에 없던 행이 새로 나타나는 팬텀 리드와는 구분된다.');
SET @q2_3 = LAST_INSERT_ID();

-- 꼬리질문 q2_4 (q2의 4번 보기) [주 태그: MVCC]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('MVCC가 읽기와 쓰기를 함께 처리하는 방법', 'MVCC(다중 버전 동시성 제어)가 읽기 작업과 쓰기 작업이 서로를 기다리지 않게 만드는 원리로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DB',
 'MVCC는 행을 갱신할 때 기존 값을 덮어쓰지 않고 이전 버전을 따로 보관한다. 조회 트랜잭션은 자신이 시작한 시점에 맞는 과거 버전을 읽으므로, 다른 트랜잭션이 같은 행을 수정 중이어도 락을 기다릴 필요가 없다. 읽기가 쓰기를 막지 않고 쓰기도 읽기를 막지 않는다.');
SET @q2_4 = LAST_INSERT_ID();

-- 본질문(q2) 선택지 (정답 sequence = 3)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q2, '커밋한 결과가 장애 이후에도 남는지를 결정하기 위한 장치이므로, 묶지 않으면 데이터가 저장되지 않는다.', 1, FALSE, '커밋된 결과가 장애 후에도 남는 것은 트랜잭션의 지속성이 보장하는 별개의 성질이다. 트랜잭션으로 묶지 않아도 각각의 SQL은 정상적으로 저장된다.', @q2_1),
(@q2, '여러 SQL을 한 번에 보내 네트워크 왕복을 줄임으로써 실행 속도를 높이기 위한 장치다.', 2, FALSE, '네트워크 왕복을 줄이는 것은 배치 전송의 효과이지 트랜잭션의 목적이 아니다. 트랜잭션은 오히려 락과 로그 기록 때문에 비용이 늘어날 수 있다.', @q2_2),
(@q2, '여러 작업이 모두 성공하거나 모두 실패하도록 묶어, 중간에 실패해도 데이터가 어중간한 상태로 남지 않게 하기 위함이다.', 3, TRUE, '', @q2_3),
(@q2, '한 번 조회한 데이터를 트랜잭션이 끝날 때까지 캐시에 보관해 같은 조회를 생략하기 위한 장치다.', 4, FALSE, '조회 결과 캐싱은 영속성 컨텍스트나 별도 캐시 계층의 기능이다. 트랜잭션 자체는 캐싱을 목적으로 하지 않는다.', @q2_4);

-- 꼬리질문(q2_1) 선택지 (정답 sequence = 4)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q2_1, '트랜잭션이 실행되는 동안 다른 트랜잭션이 중간 상태를 보지 못하도록 막아 준다.', 1, FALSE, '중간 상태를 감추는 것은 격리성(Isolation)의 설명이다. 지속성은 커밋 이후 결과가 남는지에 대한 보장이다.', @q2),
(@q2_1, '트랜잭션이 실패하면 시작 이전 상태로 완전히 되돌려 준다.', 2, FALSE, '전부 성공하거나 전부 취소되는 성질은 원자성(Atomicity)이다.', @q2),
(@q2_1, '트랜잭션 전후로 제약조건이 깨지지 않은 상태가 유지되도록 보장한다.', 3, FALSE, '이는 일관성(Consistency)의 설명이다.', @q2),
(@q2_1, '커밋이 끝난 트랜잭션의 결과는 시스템이 비정상 종료되어도 보존된다.', 4, TRUE, '', @q2);

-- 꼬리질문(q2_2) 선택지 (정답 sequence = 1)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q2_2, '동시 처리량은 늘어날 수 있지만, 커밋되지 않은 변경까지 읽게 되어 더티 리드가 발생한다.', 1, TRUE, '', @q2),
(@q2_2, '동시 처리량과 정확성이 모두 좋아지므로 부작용 없이 성능을 얻을 수 있다.', 2, FALSE, '격리 수준은 동시성과 정확성을 맞바꾸는 선택이다. 한쪽을 얻으면 다른 쪽을 내주어야 한다.', @q2),
(@q2_2, '읽기 성능은 그대로이고 쓰기 성능만 좋아진다.', 3, FALSE, '격리 수준을 낮추면 읽을 때 걸리는 제약이 줄어드는 것이 핵심 변화다. 쓰기만 빨라진다는 서술은 맞지 않다.', @q2),
(@q2_2, '팬텀 리드는 사라지지만 더티 리드가 새로 생긴다.', 4, FALSE, '격리 수준을 낮추면 막아 주던 이상 현상이 늘어날 뿐, 이미 허용되던 현상이 사라지지는 않는다.', @q2);

-- 꼬리질문(q2_3) 선택지 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q2_3, '아직 커밋되지 않은 다른 트랜잭션의 변경을 읽어 버린 경우이며 더티 리드라고 부른다.', 1, FALSE, '더티 리드는 커밋되지 않은 값을 읽는 현상이다. 여기서는 다른 트랜잭션이 정상적으로 커밋한 뒤 값이 달라졌다.', @q2),
(@q2_3, '다시 읽는 사이에 다른 트랜잭션이 그 행을 수정하고 커밋해 값이 달라진 경우이며 반복 불가능한 읽기다.', 2, TRUE, '', @q2),
(@q2_3, '같은 조건으로 조회했는데 이전에 없던 행이 새로 나타난 경우이며 반복 불가능한 읽기다.', 3, FALSE, '없던 행이 새로 나타나는 것은 팬텀 리드다. 반복 불가능한 읽기는 기존 행의 값이 바뀌는 현상이다.', @q2),
(@q2_3, '두 트랜잭션이 서로의 락을 기다려 아무도 진행하지 못하는 경우이며 반복 불가능한 읽기다.', 4, FALSE, '서로의 락을 기다리며 멈추는 것은 데드락이다. 조회 값이 달라지는 이상 현상과는 다른 문제다.', @q2);

-- 꼬리질문(q2_4) 선택지 (정답 sequence = 3)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q2_4, '조회 트랜잭션이 읽는 동안 해당 행에 공유 락을 걸어 다른 트랜잭션의 수정을 잠시 막는다.', 1, FALSE, '락으로 막는 방식은 MVCC가 피하려는 바로 그 방식이다. MVCC는 락 없이 읽을 수 있게 하는 것이 핵심이다.', @q2),
(@q2_4, '모든 트랜잭션을 도착한 순서대로 한 번에 하나씩 실행해 충돌 자체를 없앤다.', 2, FALSE, '직렬 실행은 충돌을 없애지만 동시성도 함께 없앤다. MVCC는 동시에 진행시키면서 충돌을 피하는 방법이다.', @q2),
(@q2_4, '행을 수정할 때 이전 값을 따로 보관해 두고, 조회는 자신의 시점에 맞는 과거 버전을 읽는다.', 3, TRUE, '', @q2),
(@q2_4, '조회 결과를 별도 캐시에 저장해 두고 원본이 바뀌어도 캐시를 그대로 반환한다.', 4, FALSE, '캐시를 무효화하지 않고 계속 반환하면 오래된 값을 잘못 보게 된다. MVCC는 트랜잭션 시점에 맞는 일관된 버전을 고르는 방식이지 단순 캐싱이 아니다.', @q2);

-- ------------------------------------------------------------
-- 그룹 q3 · 클러스터: 락과 동시성 제어
-- ------------------------------------------------------------
-- 본질문 q3 [주 태그: 락]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('공유 락과 배타 락의 관계', '데이터베이스의 공유 락(Shared Lock)과 배타 락(Exclusive Lock)에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '공유 락은 읽기를 위한 락으로 여러 트랜잭션이 같은 자원에 동시에 걸 수 있다. 배타 락은 변경을 위한 락으로 다른 어떤 락과도 함께 걸리지 않는다. 즉 읽기끼리는 공존하지만, 쓰기가 끼어들면 그 자원에 대해서는 혼자만 접근할 수 있다.');
SET @q3 = LAST_INSERT_ID();

-- 꼬리질문 q3_1 (q3의 1번 보기) [주 태그: 낙관적 락과 비관적 락]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('낙관적 락을 고르는 상황', '낙관적 락(Optimistic Lock)이 비관적 락보다 유리한 상황으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '낙관적 락은 락을 걸지 않고 진행한 뒤 커밋 시점에 버전이 바뀌었는지 확인해 충돌을 감지한다. 충돌이 드문 환경에서는 대기 비용이 없어 처리량이 높다. 반대로 충돌이 잦으면 실패와 재시도가 반복되므로, 그때는 처음부터 락을 잡는 비관적 락이 낫다.');
SET @q3_1 = LAST_INSERT_ID();

-- 꼬리질문 q3_2 (q3의 2번 보기) [주 태그: 트랜잭션 데드락]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('트랜잭션 데드락을 줄이는 방법', '여러 트랜잭션이 서로의 락을 기다리며 멈추는 상황을 줄이는 실무적인 방법으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '데드락은 두 트랜잭션이 서로 반대 순서로 자원을 잠글 때 잘 생긴다. 모든 트랜잭션이 자원을 같은 순서로 잠그도록 규칙을 정하면 순환 대기가 만들어지지 않아 데드락 자체가 줄어든다. 여기에 트랜잭션 범위를 짧게 유지하면 락을 쥐는 시간이 줄어 충돌 확률이 더 낮아진다.');
SET @q3_2 = LAST_INSERT_ID();

-- 꼬리질문 q3_3 (q3의 3번 보기) [주 태그: 트랜잭션 전파]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('REQUIRES_NEW 전파 속성의 동작', '이미 트랜잭션이 진행 중인 상태에서 전파 속성이 REQUIRES_NEW인 메서드를 호출했을 때의 동작으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DB',
 'REQUIRES_NEW는 기존 트랜잭션을 잠시 보류하고 완전히 새로운 트랜잭션을 시작한다. 두 트랜잭션은 서로 독립적이어서 안쪽이 롤백해도 바깥쪽은 영향을 받지 않고, 반대로 바깥쪽이 롤백해도 이미 커밋된 안쪽은 되돌아가지 않는다. 로그 기록처럼 본 작업의 성패와 무관하게 남겨야 하는 처리에 쓴다.');
SET @q3_3 = LAST_INSERT_ID();

-- 꼬리질문 q3_4 (q3의 4번 보기) [주 태그: 커넥션 풀]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('커넥션 풀을 쓰는 이유', '애플리케이션이 데이터베이스 커넥션 풀을 사용하는 이유로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '데이터베이스 커넥션은 TCP 연결과 인증을 거쳐야 해서 만드는 비용이 크다. 커넥션 풀은 미리 만들어 둔 커넥션을 빌려주고 반납받아 재사용함으로써 이 비용을 없앤다. 동시에 풀 크기가 곧 동시 처리 가능한 요청 수의 상한이 되어 DB로 몰리는 부하를 제한하는 역할도 한다.');
SET @q3_4 = LAST_INSERT_ID();

-- 본질문(q3) 선택지 (정답 sequence = 4)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q3, '공유 락과 배타 락 모두 한 번에 하나의 트랜잭션만 걸 수 있어 읽기끼리도 서로를 기다린다.', 1, FALSE, '공유 락은 여러 트랜잭션이 동시에 걸 수 있다. 읽기끼리 서로를 막는다면 조회가 많은 서비스는 사실상 직렬로 처리될 것이다.', @q3_1),
(@q3, '배타 락은 다른 배타 락만 막고 공유 락과는 함께 걸릴 수 있다.', 2, FALSE, '배타 락은 어떤 락과도 함께 걸리지 않는다. 변경 중인 데이터를 다른 트랜잭션이 읽어 가면 일관성이 깨지기 때문이다.', @q3_2),
(@q3, '락은 트랜잭션이 끝나는 것과 무관하게 일정 시간이 지나면 자동으로 풀린다.', 3, FALSE, '락은 원칙적으로 트랜잭션이 커밋되거나 롤백될 때 해제된다. 타임아웃은 기다리다 지친 쪽이 실패하는 장치이지 락을 쥔 쪽이 놓는 것이 아니다.', @q3_3),
(@q3, '공유 락은 여러 트랜잭션이 동시에 걸 수 있지만, 배타 락은 다른 어떤 락과도 함께 걸리지 않는다.', 4, TRUE, '', @q3_4);

-- 꼬리질문(q3_1) 선택지 (정답 sequence = 1)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q3_1, '같은 데이터를 동시에 수정하는 일이 드물어 충돌이 거의 나지 않는 경우', 1, TRUE, '', @q3),
(@q3_1, '재고 차감처럼 같은 행에 수정 요청이 몰려 충돌이 빈번한 경우', 2, FALSE, '충돌이 잦으면 낙관적 락은 커밋 시점에 계속 실패해 재시도가 반복된다. 이런 경우에는 처음부터 락을 잡는 비관적 락이 유리하다.', @q3),
(@q3_1, '트랜잭션이 매우 길어 락을 오래 쥐고 있어야 하는 경우', 3, FALSE, '트랜잭션이 길다는 사실만으로 낙관적 락이 유리해지지는 않는다. 오히려 그사이 다른 트랜잭션이 값을 바꿀 확률이 높아져 커밋 시점에 실패하기 쉽다.', @q3),
(@q3_1, '충돌이 나면 절대 재시도할 수 없어 한 번에 반드시 성공해야 하는 경우', 4, FALSE, '낙관적 락은 충돌을 감지하면 실패시키고 재시도하는 것을 전제로 한다. 재시도가 불가능하다면 오히려 맞지 않는 방식이다.', @q3);

-- 꼬리질문(q3_2) 선택지 (정답 sequence = 3)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q3_2, '트랜잭션의 격리 수준을 가장 높은 SERIALIZABLE로 올린다.', 1, FALSE, '격리 수준을 높이면 락 범위가 넓어져 오히려 데드락이 더 잘 생긴다. 이상 현상은 막을 수 있어도 데드락 대책은 되지 못한다.', @q3),
(@q3_2, '트랜잭션 하나가 다루는 테이블 수를 늘려 한 번에 처리하게 한다.', 2, FALSE, '한 트랜잭션이 더 많은 자원을 오래 쥐게 되어 다른 트랜잭션과 부딪힐 가능성이 커진다.', @q3),
(@q3_2, '모든 트랜잭션이 자원을 같은 순서로 잠그도록 규칙을 정하고, 트랜잭션 범위를 짧게 유지한다.', 3, TRUE, '', @q3),
(@q3_2, '데드락이 감지되면 두 트랜잭션을 모두 커밋해 대기를 끝낸다.', 4, FALSE, '서로 완료되지 않은 상태이므로 둘 다 커밋할 수 없다. DBMS는 한쪽을 희생자로 골라 롤백시켜 순환을 끊는다.', @q3);

-- 꼬리질문(q3_3) 선택지 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q3_3, '진행 중이던 트랜잭션에 그대로 합류해 하나의 트랜잭션으로 처리된다.', 1, FALSE, '기존 트랜잭션에 합류하는 것은 기본값인 REQUIRED의 동작이다.', @q3),
(@q3_3, '기존 트랜잭션을 잠시 보류하고 독립된 새 트랜잭션을 시작하므로, 안쪽이 롤백해도 바깥쪽은 영향을 받지 않는다.', 2, TRUE, '', @q3),
(@q3_3, '트랜잭션 없이 실행되며 각 SQL이 개별적으로 즉시 반영된다.', 3, FALSE, '트랜잭션 없이 실행하는 것은 NOT_SUPPORTED에 가깝다. REQUIRES_NEW는 분명히 새 트랜잭션을 연다.', @q3),
(@q3_3, '이미 트랜잭션이 있으므로 예외가 발생하며 호출이 거부된다.', 4, FALSE, '기존 트랜잭션이 있을 때 예외를 던지는 것은 NEVER의 동작이다.', @q3);

-- 꼬리질문(q3_4) 선택지 (정답 sequence = 4)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q3_4, '커넥션을 무제한으로 만들 수 있게 해 동시 요청이 아무리 많아도 대기 없이 처리하기 위해서다.', 1, FALSE, '커넥션 풀은 오히려 개수의 상한을 두는 장치다. 커넥션을 무제한으로 늘리면 DB가 먼저 무너진다.', @q3),
(@q3_4, '쿼리 결과를 풀에 저장해 두었다가 같은 쿼리가 오면 DB에 가지 않고 반환하기 위해서다.', 2, FALSE, '결과를 저장해 재사용하는 것은 캐시의 역할이다. 커넥션 풀이 재사용하는 대상은 결과가 아니라 연결 그 자체다.', @q3),
(@q3_4, '트랜잭션이 실패했을 때 자동으로 롤백해 주기 위해서다.', 3, FALSE, '롤백은 트랜잭션 관리의 몫이다. 커넥션 풀은 연결을 빌려주고 반납받는 역할만 한다.', @q3),
(@q3_4, '연결을 만들 때 드는 비용을 없애려고 미리 만들어 둔 커넥션을 빌려주고 반납받아 재사용하기 위해서다.', 4, TRUE, '', @q3);

-- ------------------------------------------------------------
-- 그룹 q4 · 클러스터: 스키마 설계
-- ------------------------------------------------------------
-- 본질문 q4 [주 태그: 정규화]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('정규화가 해결하려는 문제', '관계형 데이터베이스에서 정규화를 수행하는 목적으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '정규화는 중복된 데이터를 제거하고 속성을 관련 있는 테이블로 분리하는 과정이다. 중복이 사라지면 한 값을 여러 곳에서 따로 관리하다 생기는 삽입·갱신·삭제 이상 현상이 없어진다. 조회 성능을 높이려는 작업이 아니라 데이터 무결성을 지키려는 작업이다.');
SET @q4 = LAST_INSERT_ID();

-- 꼬리질문 q4_1 (q4의 1번 보기) [주 태그: 반정규화]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('반정규화를 적용할 때의 판단 기준', '이미 정규화된 스키마에 반정규화를 적용하려 할 때 가장 적절한 판단은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '반정규화는 중복을 의도적으로 허용해 조인을 줄이고 조회 성능을 얻는 기법이다. 대신 같은 값을 여러 곳에서 맞춰 줘야 하므로 정합성 관리 부담이 늘어난다. 따라서 정규화를 기본으로 두고, 측정으로 병목이 확인된 지점에 한정해 적용하는 것이 원칙이다.');
SET @q4_1 = LAST_INSERT_ID();

-- 꼬리질문 q4_2 (q4의 2번 보기) [주 태그: 키와 제약조건]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('기본 키와 유니크 제약의 차이', '기본 키(Primary Key)와 유니크(Unique) 제약의 차이로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '둘 다 값의 중복을 막는다는 점은 같지만, 기본 키는 테이블당 하나만 둘 수 있고 NULL을 허용하지 않는다. 유니크 제약은 여러 개를 둘 수 있고 구현에 따라 NULL을 허용한다. 기본 키는 행을 식별하는 대표 수단이라는 의미까지 갖는다.');
SET @q4_2 = LAST_INSERT_ID();

-- 꼬리질문 q4_3 (q4의 3번 보기) [주 태그: NULL 처리]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('NULL이 비교와 집계에서 다뤄지는 방식', 'SQL에서 NULL이 비교 연산과 집계 함수에서 처리되는 방식으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 'NULL은 값이 없다가 아니라 값을 알 수 없다는 뜻이다. 그래서 = 나 <> 로 비교하면 참도 거짓도 아닌 결과가 나와 IS NULL을 써야 하고, COUNT(컬럼)이나 SUM 같은 집계 함수는 NULL인 행을 아예 제외하고 계산한다. COUNT(*)만은 행 자체를 세므로 NULL과 무관하다.');
SET @q4_3 = LAST_INSERT_ID();

-- 꼬리질문 q4_4 (q4의 4번 보기) [주 태그: RDB와 NoSQL]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('NoSQL을 선택하기 적합한 상황', '관계형 데이터베이스 대신 NoSQL을 선택하기에 적합한 상황으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 'NoSQL은 스키마가 고정되지 않아 형태가 자주 바뀌거나 제각각인 데이터를 담기 좋고, 수평 확장을 전제로 설계되어 대량 데이터를 여러 노드에 나눠 담기 유리하다. 반대로 여러 테이블에 걸친 복잡한 조인과 강한 트랜잭션 보장이 필요한 업무에는 관계형 데이터베이스가 더 맞는다.');
SET @q4_4 = LAST_INSERT_ID();

-- 본질문(q4) 선택지 (정답 sequence = 1)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q4, '데이터 중복을 없애 삽입·갱신·삭제 시 생기는 이상 현상을 방지하고 무결성을 높이기 위함이다.', 1, TRUE, '', @q4_1),
(@q4, '테이블을 하나로 합쳐 조인을 없앰으로써 조회 성능을 높이기 위함이다.', 2, FALSE, '테이블을 합쳐 조인을 줄이는 것은 반정규화다. 정규화는 오히려 테이블을 나누므로 조인이 늘어난다.', @q4_2),
(@q4, '모든 컬럼이 NULL을 허용하도록 만들어 데이터 입력을 자유롭게 하기 위함이다.', 3, FALSE, '정규화는 NULL 허용 여부와 직접 관련이 없다. 오히려 속성을 알맞은 테이블로 분리하면 의미 없는 NULL이 줄어든다.', @q4_3),
(@q4, '데이터를 여러 서버에 나눠 담아 저장 용량의 한계를 넘기 위함이다.', 4, FALSE, '데이터를 여러 서버에 분산하는 것은 샤딩이다. 정규화는 한 데이터베이스 안에서 스키마를 정리하는 작업이다.', @q4_4);

-- 꼬리질문(q4_1) 선택지 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q4_1, '조인이 하나라도 들어가는 쿼리는 모두 반정규화 대상으로 삼는다.', 1, FALSE, '조인이 있다는 사실만으로 문제가 되지는 않는다. 근거 없이 중복을 늘리면 정합성 관리 비용만 커진다.', @q4),
(@q4_1, '정규화를 기본으로 두고, 측정으로 병목이 확인된 지점에 한정해 적용한다.', 2, TRUE, '', @q4),
(@q4_1, '반정규화는 중복을 허용하므로 정합성 관리 부담이 오히려 줄어든다.', 3, FALSE, '같은 값이 여러 곳에 존재하게 되므로 한쪽만 갱신되는 상황을 막기 위한 추가 장치가 필요하다. 부담은 늘어난다.', @q4),
(@q4_1, '반정규화를 적용하면 조회와 쓰기 성능이 함께 좋아지므로 되도록 넓게 적용한다.', 4, FALSE, '중복된 값을 모두 갱신해야 하므로 쓰기 비용은 오히려 늘어난다. 조회 성능을 쓰기 비용으로 사는 선택이다.', @q4);

-- 꼬리질문(q4_2) 선택지 (정답 sequence = 4)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q4_2, '기본 키는 중복을 허용하지만 유니크 제약은 허용하지 않는다.', 1, FALSE, '기본 키도 중복을 허용하지 않는다. 두 제약 모두 값의 유일성을 보장한다.', @q4),
(@q4_2, '유니크 제약은 테이블당 하나만 둘 수 있고 기본 키는 여러 개를 둘 수 있다.', 2, FALSE, '설명이 반대다. 하나만 둘 수 있는 쪽이 기본 키이고, 유니크 제약은 여러 개를 둘 수 있다.', @q4),
(@q4_2, '기본 키는 인덱스를 만들지 않지만 유니크 제약은 인덱스를 만든다.', 3, FALSE, '두 제약 모두 유일성을 확인하기 위해 인덱스를 사용한다. 기본 키에 인덱스가 없다는 서술은 틀렸다.', @q4),
(@q4_2, '기본 키는 테이블당 하나만 두고 NULL을 허용하지 않지만, 유니크 제약은 여러 개를 둘 수 있고 NULL을 허용하기도 한다.', 4, TRUE, '', @q4);

-- 꼬리질문(q4_3) 선택지 (정답 sequence = 3)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q4_3, 'NULL은 빈 문자열과 같은 값이므로 = '''' 로 비교하면 찾을 수 있다.', 1, FALSE, 'NULL과 빈 문자열은 서로 다르다. 빈 문자열은 길이가 0인 값이 존재하는 것이고 NULL은 값 자체를 알 수 없는 상태다.', @q4),
(@q4_3, 'NULL도 하나의 값이므로 SUM이나 AVG 계산에 0으로 포함된다.', 2, FALSE, '집계 함수는 NULL인 행을 계산에서 제외한다. 0으로 바꿔 넣지 않으므로 AVG의 분모에서도 빠진다.', @q4),
(@q4_3, '= 나 <> 로는 판별할 수 없어 IS NULL을 써야 하고, COUNT(컬럼)이나 SUM은 NULL인 행을 제외하고 계산한다.', 3, TRUE, '', @q4),
(@q4_3, 'NULL이 하나라도 있는 컬럼은 인덱스를 만들 수 없다.', 4, FALSE, 'NULL이 포함된 컬럼에도 인덱스를 만들 수 있다. NULL의 비교 규칙과 인덱스 생성 가능 여부는 별개 문제다.', @q4);

-- 꼬리질문(q4_4) 선택지 (정답 sequence = 1)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q4_4, '저장할 데이터의 형태가 자주 바뀌거나 제각각이고, 데이터를 여러 노드에 나눠 담아 확장해야 하는 경우', 1, TRUE, '', @q4),
(@q4_4, '여러 테이블을 조인해 집계하는 복잡한 통계 쿼리가 업무의 중심인 경우', 2, FALSE, '복잡한 조인은 관계형 데이터베이스가 강한 영역이다. NoSQL은 조인을 제한하거나 애플리케이션에서 직접 처리하게 하는 경우가 많다.', @q4),
(@q4_4, '여러 테이블에 걸친 갱신이 반드시 함께 성공하거나 함께 실패해야 하는 경우', 3, FALSE, '여러 대상에 걸친 강한 트랜잭션 보장은 관계형 데이터베이스가 더 안정적으로 제공한다.', @q4),
(@q4_4, '데이터 구조가 고정되어 있고 제약조건으로 무결성을 엄격히 강제해야 하는 경우', 4, FALSE, '스키마와 제약조건으로 무결성을 강제하는 것은 관계형 데이터베이스의 특징이다. NoSQL은 스키마를 느슨하게 두는 쪽이다.', @q4);

-- ------------------------------------------------------------
-- 그룹 q5 · 클러스터: 조인과 ORM
-- ------------------------------------------------------------
-- 본질문 q5 [주 태그: 조인]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('INNER JOIN과 LEFT OUTER JOIN의 결과 차이', '주문 테이블과 결제 테이블을 조인할 때 INNER JOIN과 LEFT OUTER JOIN의 결과 차이로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 'INNER JOIN은 양쪽 모두에서 조인 조건을 만족하는 행만 남긴다. LEFT OUTER JOIN은 왼쪽 테이블의 행을 모두 남기고, 짝이 없으면 오른쪽 컬럼을 NULL로 채운다. 따라서 결제가 아직 없는 주문까지 보고 싶다면 LEFT OUTER JOIN을 써야 한다.');
SET @q5 = LAST_INSERT_ID();

-- 꼬리질문 q5_1 (q5의 1번 보기) [주 태그: 서브쿼리]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('상관 서브쿼리가 느려질 수 있는 이유', 'WHERE 절에서 바깥 쿼리의 컬럼을 참조하는 상관 서브쿼리(Correlated Subquery)가 성능 문제를 일으킬 수 있는 이유로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DB',
 '상관 서브쿼리는 바깥 쿼리의 값을 받아 동작하므로, 원칙적으로 바깥 쿼리가 처리하는 행마다 서브쿼리가 다시 평가된다. 바깥 결과가 많을수록 반복 횟수가 늘어 비용이 커진다. 그래서 조인이나 EXISTS로 바꿔 한 번에 처리하도록 고치는 튜닝을 자주 한다.');
SET @q5_1 = LAST_INSERT_ID();

-- 꼬리질문 q5_2 (q5의 2번 보기) [주 태그: 집계와 GROUP BY]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('WHERE와 HAVING의 차이', 'GROUP BY를 사용하는 쿼리에서 WHERE 절과 HAVING 절의 차이로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 'WHERE는 그룹을 만들기 전에 개별 행을 걸러내고, HAVING은 그룹으로 묶어 집계한 결과를 걸러낸다. 따라서 COUNT나 SUM 같은 집계 결과를 조건으로 쓰려면 HAVING을 써야 한다. 집계와 무관한 조건은 WHERE에서 먼저 걸러야 묶을 행이 줄어 유리하다.');
SET @q5_2 = LAST_INSERT_ID();

-- 꼬리질문 q5_3 (q5의 3번 보기) [주 태그: ORM과 영속성 컨텍스트]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('영속성 컨텍스트의 변경 감지', 'JPA에서 조회한 엔티티의 필드 값을 바꾸기만 하고 별도의 저장 메서드를 호출하지 않았는데도 UPDATE가 실행되는 이유로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '영속성 컨텍스트는 엔티티를 처음 읽어 온 시점의 상태를 스냅샷으로 보관한다. 트랜잭션이 커밋되며 플러시가 일어날 때 현재 값과 스냅샷을 비교해 달라진 필드가 있으면 UPDATE 문을 만들어 보낸다. 이를 변경 감지(더티 체킹)라고 한다.');
SET @q5_3 = LAST_INSERT_ID();

-- 꼬리질문 q5_4 (q5의 4번 보기) [주 태그: N+1 문제]
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('N+1 문제가 발생하는 과정', 'ORM을 사용할 때 발생하는 N+1 문제에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DB',
 '목록을 한 번의 쿼리로 조회한 뒤 각 엔티티의 연관 데이터를 지연 로딩으로 꺼내면, 조회된 행 수 N만큼 추가 쿼리가 따라 나가 총 N+1번의 쿼리가 실행된다. 페치 조인이나 배치 사이즈 설정으로 연관 데이터를 함께 가져오면 해결된다.');
SET @q5_4 = LAST_INSERT_ID();

-- 본질문(q5) 선택지 (정답 sequence = 1)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q5, 'INNER JOIN은 양쪽 조건을 만족하는 행만 남기고, LEFT OUTER JOIN은 왼쪽 행을 모두 남기며 짝이 없으면 NULL로 채운다.', 1, TRUE, '', @q5_1),
(@q5, '두 조인은 결과 행 수만 다를 뿐 어떤 경우에도 NULL이 생기지 않는다.', 2, FALSE, 'LEFT OUTER JOIN은 짝이 없는 행의 오른쪽 컬럼을 NULL로 채운다. NULL이 생기지 않는다는 서술은 틀렸다.', @q5_2),
(@q5, 'LEFT OUTER JOIN은 양쪽 모두에 존재하는 행만 남기므로 INNER JOIN보다 결과가 항상 적다.', 3, FALSE, '양쪽에 모두 있는 행만 남기는 것이 INNER JOIN이다. LEFT OUTER JOIN의 결과는 INNER JOIN보다 적을 수 없다.', @q5_3),
(@q5, '조인 방식에 따라 결과 집합이 달라지지는 않고 실행 속도만 달라진다.', 4, FALSE, '조인 종류는 어떤 행을 남길지를 정하므로 결과 집합 자체가 달라진다. 성능만의 문제가 아니다.', @q5_4);

-- 꼬리질문(q5_1) 선택지 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q5_1, '서브쿼리는 항상 임시 테이블로 만들어져 디스크에 기록되기 때문이다.', 1, FALSE, '임시 테이블이 만들어질 수는 있지만 항상 그런 것도, 항상 디스크에 쓰이는 것도 아니다. 상관 서브쿼리의 핵심 비용은 반복 평가다.', @q5),
(@q5_1, '바깥 쿼리의 값을 받아 동작하므로 바깥 쿼리가 처리하는 행마다 다시 평가될 수 있기 때문이다.', 2, TRUE, '', @q5),
(@q5_1, '서브쿼리 안에서는 인덱스를 전혀 사용할 수 없기 때문이다.', 3, FALSE, '서브쿼리 안에서도 인덱스를 사용할 수 있다. 다만 반복 실행되면 그만큼 인덱스 탐색도 반복된다.', @q5),
(@q5_1, '상관 서브쿼리는 결과를 캐시하지 못하도록 표준에 금지되어 있기 때문이다.', 4, FALSE, '그런 표준 규정은 없다. 오히려 DBMS는 가능한 경우 조인으로 변형하거나 결과를 재사용하는 최적화를 시도한다.', @q5);

-- 꼬리질문(q5_2) 선택지 (정답 sequence = 3)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q5_2, '둘은 완전히 같은 기능이며 GROUP BY가 있을 때는 어느 쪽을 써도 결과가 같다.', 1, FALSE, '적용되는 시점이 다르다. 집계 결과를 조건으로 쓰는 경우 WHERE에서는 아예 쓸 수 없다.', @q5),
(@q5_2, 'HAVING은 그룹을 만들기 전 개별 행을 거르고, WHERE는 집계 결과를 거른다.', 2, FALSE, '설명이 반대다. 개별 행을 먼저 거르는 쪽이 WHERE이고, 집계 결과를 거르는 쪽이 HAVING이다.', @q5),
(@q5_2, 'WHERE는 그룹을 만들기 전 개별 행을 거르고, HAVING은 집계한 결과를 거른다.', 3, TRUE, '', @q5),
(@q5_2, 'WHERE는 인덱스를 쓸 수 있고 HAVING도 항상 같은 인덱스를 그대로 활용한다.', 4, FALSE, 'HAVING은 이미 집계가 끝난 결과에 적용되므로 원본 컬럼의 인덱스를 그대로 쓸 수 있는 상황이 아니다.', @q5);

-- 꼬리질문(q5_3) 선택지 (정답 sequence = 4)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q5_3, '엔티티의 setter가 호출되는 순간 곧바로 UPDATE 문이 데이터베이스로 전송되기 때문이다.', 1, FALSE, '값을 바꾸는 즉시 전송되지 않는다. 쓰기 지연 저장소에 모아 두었다가 플러시 시점에 한꺼번에 내보낸다.', @q5),
(@q5_3, '조회한 엔티티가 준영속 상태여서 영속성 컨텍스트가 자동으로 다시 저장하기 때문이다.', 2, FALSE, '준영속 상태는 영속성 컨텍스트의 관리에서 벗어난 상태라 변경 감지가 동작하지 않는다. 오히려 영속 상태여야 한다.', @q5),
(@q5_3, 'JPA가 모든 엔티티를 매 트랜잭션마다 무조건 UPDATE하기 때문이다.', 3, FALSE, '무조건 갱신한다면 변경되지 않은 엔티티까지 쿼리가 나갈 것이다. 실제로는 달라진 것이 있을 때만 UPDATE를 만든다.', @q5),
(@q5_3, '처음 읽어 온 시점의 스냅샷과 현재 값을 플러시 시점에 비교해, 달라진 필드가 있으면 UPDATE를 만들기 때문이다.', 4, TRUE, '', @q5);

-- 꼬리질문(q5_4) 선택지 (정답 sequence = 2)
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@q5_4, '연관 관계를 즉시 로딩으로 설정하면 항상 사라지므로 페치 전략만 바꾸면 되는 문제다.', 1, FALSE, '즉시 로딩으로 바꿔도 연관 데이터를 건별로 조회하면 추가 쿼리는 그대로 나간다. 로딩 시점이 앞당겨질 뿐 쿼리 수가 줄어든다는 보장은 없다.', @q5),
(@q5_4, '목록을 한 번 조회한 뒤 각 엔티티의 연관 데이터를 따로 꺼내면서 조회된 행 수만큼 추가 쿼리가 나가는 문제다.', 2, TRUE, '', @q5),
(@q5_4, '하나의 쿼리에 조인을 N개 이상 넣었을 때 옵티마이저가 계획을 세우지 못하는 문제다.', 3, FALSE, '조인 개수가 많아 생기는 최적화 문제와는 다르다. N+1은 쿼리 하나가 복잡해지는 것이 아니라 쿼리 개수가 늘어나는 문제다.', @q5),
(@q5_4, '같은 데이터를 N개의 트랜잭션이 동시에 수정해 충돌이 생기는 문제다.', 4, FALSE, '동시 수정 충돌은 락과 동시성 제어의 영역이다. N+1은 조회 시 발생하는 쿼리 개수 문제다.', @q5);


-- ============================================================
-- 서술형 (ESSAY) — 50문항 (태그 25개 × 2문항)
-- ============================================================

-- e1 [주 태그: 인덱스] — 원리와 트레이드오프
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('인덱스의 동작 원리와 대가', '데이터베이스 인덱스가 조회 성능을 높이는 원리를 설명하고, 인덱스를 늘릴 때 치르게 되는 대가를 함께 논하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '인덱스는 컬럼 값을 정렬한 별도의 자료구조(대개 B-Tree)에 실제 행을 찾아갈 정보를 함께 담은 것입니다. 정렬되어 있으므로 이진 탐색과 유사한 방식으로 후보 범위를 빠르게 좁혀, 테이블 전체를 처음부터 훑는 풀 스캔 없이 원하는 행에 도달할 수 있습니다. 대가는 세 가지입니다. 첫째, 인덱스를 저장할 공간이 추가로 듭니다. 둘째, INSERT·UPDATE·DELETE마다 인덱스도 함께 갱신해야 해서 쓰기 성능이 떨어집니다. 셋째, 인덱스가 많아지면 옵티마이저가 선택할 후보가 늘어 계획 수립이 복잡해지고 잘못된 인덱스를 고를 여지도 생깁니다. 따라서 조회 패턴을 근거로 꼭 필요한 인덱스만 만드는 것이 좋습니다.');
SET @e1 = LAST_INSERT_ID();

-- e2 [주 태그: 인덱스] — 인덱스가 무력해지는 조건
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('인덱스를 만들어도 타지 않는 경우', '인덱스가 분명히 존재하는데도 쿼리가 인덱스를 사용하지 못하거나, 사용하고도 이득이 없는 경우를 예를 들어 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '크게 세 부류가 있습니다. 첫째, 인덱스 컬럼을 가공한 경우입니다. WHERE DATE(created_at) = ? 처럼 컬럼에 함수를 씌우거나 타입이 달라 암묵적 형변환이 일어나면 저장된 값의 정렬 순서를 쓸 수 없어 인덱스를 타지 못합니다. 앞부분이 와일드카드로 열린 LIKE도 같은 이유로 탐색에 쓸 수 없습니다. 둘째, 선택도가 낮은 경우입니다. 성별처럼 값의 종류가 적어 조건에 해당하는 행이 전체의 상당 부분이면, 인덱스로 위치를 찾은 뒤 테이블을 다시 읽는 비용이 커져 옵티마이저가 풀 스캔을 고르는 편이 낫다고 판단합니다. 셋째, 복합 인덱스에서 선행 컬럼이 조건에 없는 경우입니다. 정렬의 출발점이 없어 인덱스를 제대로 활용할 수 없습니다. 통계 정보가 낡아 옵티마이저가 잘못 추정하는 경우도 원인이 됩니다.');
SET @e2 = LAST_INSERT_ID();

-- e3 [주 태그: 복합 인덱스] — 컬럼 순서 설계
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('복합 인덱스의 컬럼 순서를 정하는 기준', '복합 인덱스를 만들 때 컬럼 순서를 어떤 기준으로 정해야 하는지, 순서가 잘못되면 어떤 일이 벌어지는지 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '복합 인덱스는 선행 컬럼으로 먼저 정렬하고 그 안에서 다음 컬럼을 정렬한 구조입니다. 따라서 순서를 정할 때는 첫째, 조건에 등호(=)로 자주 쓰이는 컬럼을 앞에 둡니다. 범위 조건(>, <, BETWEEN)이 들어간 컬럼 뒤쪽은 정렬이 흐트러져 인덱스를 온전히 활용하기 어려우므로 범위 조건 컬럼은 뒤로 보냅니다. 둘째, 같은 조건이라면 값의 종류가 많아 결과를 크게 줄여 주는 컬럼을 앞에 둡니다. 셋째, ORDER BY나 GROUP BY에 쓰이는 순서와 맞추면 정렬 작업을 생략할 수 있습니다. 순서가 잘못되면 선행 컬럼이 조건에 없을 때 탐색 시작점을 잡지 못해 인덱스를 타지 못하고, 결국 그 인덱스를 위해 쓰기 비용과 저장 공간만 치르게 됩니다.');
SET @e3 = LAST_INSERT_ID();

-- e4 [주 태그: 복합 인덱스] — 단일 인덱스 여러 개와의 비교
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('복합 인덱스 하나와 단일 인덱스 여러 개', '컬럼 두 개를 조건으로 자주 조회할 때, 복합 인덱스 하나를 만드는 것과 단일 인덱스를 각각 만드는 것의 차이를 비교하시오.', 'ESSAY', 'HIGH', 'DB',
 '두 컬럼을 함께 조건으로 쓰는 쿼리라면 복합 인덱스 하나가 대체로 유리합니다. 복합 인덱스는 두 컬럼의 조합으로 정렬되어 있어 한 번의 탐색으로 후보를 최종 범위까지 좁힐 수 있습니다. 반면 단일 인덱스가 각각 있으면 옵티마이저는 보통 둘 중 더 유리한 하나만 사용하고 나머지 조건은 읽어 온 행에서 걸러냅니다. 두 인덱스의 결과를 교집합으로 합치는 방식을 쓸 수도 있지만 각각의 결과를 모아 병합하는 추가 비용이 들어 항상 이득은 아닙니다. 다만 두 컬럼을 각각 단독으로 조회하는 패턴도 잦다면 단일 인덱스가 필요할 수 있고, 복합 인덱스는 선행 컬럼 단독 조회에는 쓸 수 있지만 후행 컬럼 단독 조회에는 쓸 수 없다는 점을 함께 고려해야 합니다.');
SET @e4 = LAST_INSERT_ID();

-- e5 [주 태그: 커버링 인덱스] — 개념과 효과
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('커버링 인덱스가 빠른 이유', '커버링 인덱스가 무엇인지 설명하고, 일반적인 인덱스 조회보다 빠른 이유를 처리 과정과 함께 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '커버링 인덱스는 쿼리가 필요로 하는 컬럼을 인덱스가 모두 포함하고 있어, 인덱스만 읽고 결과를 만들 수 있는 상태를 말합니다. 일반적인 인덱스 조회는 두 단계로 진행됩니다. 먼저 인덱스에서 조건에 맞는 항목을 찾아 행의 위치를 얻고, 그 위치로 테이블에 접근해 나머지 컬럼을 읽어 옵니다. 이 두 번째 단계는 인덱스 순서와 테이블의 물리적 순서가 달라 임의 접근이 되기 쉬워 비용이 큽니다. 커버링 인덱스는 이 단계 자체가 필요 없어집니다. 인덱스는 대개 테이블보다 작아 캐시에 올라가기도 유리하므로 효과가 큽니다. 다만 컬럼을 많이 포함시킬수록 인덱스가 커져 쓰기 비용과 공간이 늘어나므로 무한정 넓힐 수는 없습니다.');
SET @e5 = LAST_INSERT_ID();

-- e6 [주 태그: 커버링 인덱스] — 적용 판단
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('커버링 인덱스를 적용할지 판단하기', '자주 실행되는 조회 쿼리를 커버링 인덱스로 최적화할지 판단할 때 고려해야 할 점을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '먼저 그 쿼리가 실제로 병목인지 확인해야 합니다. 실행 계획에서 인덱스를 탄 뒤 테이블 접근이 많이 발생하는지, 반환 행 수 대비 읽는 행 수가 큰지를 봅니다. 다음으로 SELECT 목록과 WHERE, ORDER BY에 쓰이는 컬럼을 모두 담을 수 있는지 확인합니다. 이때 담아야 할 컬럼이 지나치게 많거나 TEXT 같은 큰 타입이 포함되면 인덱스가 비대해져 이득보다 손해가 큽니다. 또한 그 테이블의 쓰기 빈도를 봐야 합니다. 쓰기가 잦은 테이블에 넓은 인덱스를 추가하면 갱신 비용이 크게 늘어납니다. 마지막으로 SELECT * 처럼 컬럼이 고정되지 않은 쿼리는 커버링이 성립하지 않으므로, 필요한 컬럼만 명시하도록 쿼리를 먼저 정리하는 것이 순서입니다.');
SET @e6 = LAST_INSERT_ID();

-- e7 [주 태그: 클러스터드 인덱스] — 보조 인덱스와의 관계
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('클러스터드 인덱스와 보조 인덱스의 관계', '클러스터드 인덱스와 보조 인덱스의 구조적 차이를 설명하고, 보조 인덱스로 조회할 때 어떤 과정을 거치는지 서술하시오.', 'ESSAY', 'HIGH', 'DB',
 '클러스터드 인덱스는 인덱스 키 순서대로 실제 데이터 행을 저장합니다. 리프 노드에 행 전체가 들어 있으므로 데이터 배치 자체가 인덱스이고, 그래서 테이블당 하나만 존재할 수 있습니다. 보조 인덱스는 인덱스 키와, 해당 행을 찾아갈 정보만 담은 별도 구조입니다. InnoDB에서는 이 정보로 클러스터드 인덱스의 키(대개 기본 키)를 저장합니다. 따라서 보조 인덱스로 조회하면 먼저 보조 인덱스에서 조건에 맞는 항목을 찾아 기본 키 값을 얻고, 그 값으로 클러스터드 인덱스를 다시 탐색해 실제 행을 읽습니다. 이 두 번째 탐색을 흔히 북마크 룩업이라 부르며, 필요한 컬럼이 보조 인덱스 안에 모두 있으면(커버링) 이 단계를 건너뜁니다. 이런 구조 때문에 기본 키를 크게 잡으면 모든 보조 인덱스가 함께 커진다는 점도 유의해야 합니다.');
SET @e7 = LAST_INSERT_ID();

-- e8 [주 태그: 클러스터드 인덱스] — 기본 키 선택
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('기본 키를 순차 증가 값으로 두는 이유', 'InnoDB에서 기본 키를 UUID처럼 무작위인 값 대신 순차적으로 증가하는 값으로 두는 편이 유리한 이유를 클러스터드 인덱스 구조와 연결해 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 'InnoDB는 기본 키를 클러스터드 인덱스로 삼아 그 순서대로 데이터를 저장합니다. 기본 키가 순차적으로 증가하면 새 행은 항상 마지막 페이지 끝에 덧붙으므로, 삽입이 한 지점에 집중되고 페이지가 꽉 차면 새 페이지를 잇기만 하면 됩니다. 반면 UUID처럼 무작위 값이면 새 행이 중간중간 아무 위치에나 들어가려 하고, 이미 차 있는 페이지에 끼어들면 페이지를 둘로 쪼개는 분할이 발생합니다. 그 결과 삽입 비용이 커지고 페이지 곳곳에 빈 공간이 생겨 같은 데이터를 담는 데 더 많은 페이지를 쓰게 되며, 캐시 효율도 떨어집니다. 또한 모든 보조 인덱스가 기본 키 값을 함께 저장하므로 길이가 긴 UUID는 보조 인덱스 크기까지 함께 키웁니다. 다만 분산 환경에서 미리 식별자를 만들어야 하는 요구가 있다면 정렬 가능한 형태의 식별자를 쓰는 절충안을 고려할 수 있습니다.');
SET @e8 = LAST_INSERT_ID();

-- e9 [주 태그: 실행 계획] — 읽는 법
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('실행 계획에서 확인해야 할 항목', '느린 쿼리를 만났을 때 실행 계획에서 어떤 항목을 먼저 확인해야 하는지, 각 항목이 무엇을 알려 주는지 설명하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '먼저 접근 방식을 봅니다. 인덱스를 탔는지 풀 스캔인지, 인덱스를 탔다면 등호로 한 건을 찾는지 범위를 훑는지가 드러납니다. 다음으로 사용된 인덱스가 의도한 인덱스인지 확인합니다. 예상과 다른 인덱스를 골랐다면 통계나 조건 작성 방식에 문제가 있을 수 있습니다. 세 번째로 예상 처리 행 수를 봅니다. 실제 결과 행 수보다 훨씬 많은 행을 읽고 있다면 조건이 인덱스에서 걸러지지 않고 읽어 온 뒤 걸러지고 있다는 뜻입니다. 네 번째로 조인 순서와 방식을 확인합니다. 작은 결과 집합을 먼저 처리하도록 순서가 잡혔는지가 중요합니다. 마지막으로 임시 테이블 사용이나 별도 정렬이 표시되는지 봅니다. 이는 인덱스로 정렬을 대신하지 못하고 있다는 신호입니다. 예상 비용은 추정치이므로 실제 실행 결과를 함께 측정해 비교해야 합니다.');
SET @e9 = LAST_INSERT_ID();

-- e10 [주 태그: 실행 계획] — 통계와 옵티마이저
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('옵티마이저가 계획을 잘못 세우는 이유', '옵티마이저가 비효율적인 실행 계획을 선택하는 원인에는 어떤 것들이 있는지 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '비용 기반 옵티마이저는 통계 정보를 근거로 각 계획의 예상 비용을 계산해 가장 싼 것을 고릅니다. 따라서 통계가 실제 데이터와 어긋나면 판단이 틀어집니다. 대량 입력이나 삭제 뒤 통계를 갱신하지 않은 경우가 대표적입니다. 둘째, 데이터 분포가 심하게 치우친 경우입니다. 특정 값에만 행이 몰려 있으면 평균을 전제로 한 추정이 크게 빗나갑니다. 셋째, 조건이 복잡해 선택도를 추정하기 어려운 경우입니다. 여러 조건이 서로 연관되어 있는데 옵티마이저가 독립이라고 가정하면 행 수를 과소 추정합니다. 넷째, 컬럼에 함수를 씌우거나 형변환이 일어나 인덱스를 후보에서 제외하게 만드는 쿼리 작성 방식입니다. 대응으로는 통계 갱신, 조건을 인덱스가 탈 수 있는 형태로 고쳐 쓰기, 필요한 경우 힌트로 접근 방식을 지정하는 방법이 있습니다.');
SET @e10 = LAST_INSERT_ID();

-- e11 [주 태그: 트랜잭션] — 필요성
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('트랜잭션이 필요한 이유', '여러 SQL을 하나의 트랜잭션으로 묶어야 하는 이유를 구체적인 상황을 들어 설명하시오.', 'ESSAY', 'LOW', 'DB',
 '트랜잭션은 여러 작업을 논리적으로 쪼갤 수 없는 하나의 단위로 만듭니다. 계좌 이체를 예로 들면 A 계좌에서 출금하고 B 계좌에 입금하는 두 작업이 있는데, 출금만 반영된 상태로 장애가 나면 돈이 사라진 것처럼 보이는 잘못된 상태가 남습니다. 두 작업을 한 트랜잭션으로 묶으면 중간에 실패했을 때 이미 반영한 출금까지 되돌려 아무 일도 없었던 상태로 만들 수 있습니다. 또한 트랜잭션은 진행 중인 중간 상태를 다른 트랜잭션에게 보이지 않게 해, 이체가 끝나지 않은 시점의 어중간한 잔액을 다른 조회가 읽어 가는 일도 막아 줍니다. 요컨대 성능을 위한 장치가 아니라 데이터가 항상 올바른 상태를 유지하도록 보장하기 위한 장치입니다.');
SET @e11 = LAST_INSERT_ID();

-- e12 [주 태그: 트랜잭션] — 범위 설계
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('트랜잭션 범위를 짧게 유지해야 하는 이유', '애플리케이션에서 트랜잭션 범위를 가능한 한 짧게 잡아야 하는 이유와, 범위가 길어질 때 생기는 문제를 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '트랜잭션이 열려 있는 동안에는 커넥션을 점유하고, 변경한 자원에 대한 락도 계속 쥐고 있습니다. 범위가 길어지면 첫째, 커넥션 풀이 빠르게 고갈되어 다른 요청이 커넥션을 얻지 못하고 대기합니다. 둘째, 락을 오래 쥐고 있어 같은 자원을 다루려는 트랜잭션들이 줄줄이 밀리고, 서로 다른 순서로 자원을 잠그면 데드락 확률도 올라갑니다. 셋째, MVCC를 쓰는 DBMS에서는 오래된 트랜잭션이 살아 있는 동안 이전 버전을 정리하지 못해 저장 공간이 계속 늘어납니다. 특히 외부 API 호출이나 파일 업로드처럼 시간이 오래 걸리고 실패 가능성이 있는 작업은 트랜잭션 안에 넣지 않는 것이 좋습니다. 응답을 기다리는 내내 락과 커넥션이 묶이고, 그 작업은 롤백으로 되돌릴 수도 없기 때문입니다.');
SET @e12 = LAST_INSERT_ID();

-- e13 [주 태그: ACID] — 네 속성
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('ACID 네 가지 속성', '트랜잭션의 ACID 속성 네 가지를 각각 설명하고, 서로 어떻게 구별되는지 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '원자성(Atomicity)은 트랜잭션 안의 작업이 전부 성공하거나 전부 취소되어야 한다는 것으로, 중간까지만 반영된 상태를 남기지 않습니다. 일관성(Consistency)은 트랜잭션 전후로 데이터베이스가 정의된 규칙과 제약조건을 만족하는 상태를 유지해야 한다는 것입니다. 격리성(Isolation)은 동시에 실행되는 트랜잭션들이 서로의 중간 상태를 보지 못하게 해, 마치 순서대로 실행된 것처럼 보이게 하는 성질입니다. 지속성(Durability)은 커밋된 결과가 시스템 장애 이후에도 보존되어야 한다는 것으로, 변경 내용을 로그에 먼저 기록해 두었다가 재시작 시 복원하는 방식으로 구현합니다. 구별하자면 원자성과 지속성은 한 트랜잭션의 결과가 어떻게 남는지에 대한 보장이고, 격리성은 다른 트랜잭션과의 관계에 대한 보장이며, 일관성은 나머지 셋이 지켜졌을 때 결과적으로 달성되는 목표에 가깝습니다.');
SET @e13 = LAST_INSERT_ID();

-- e14 [주 태그: ACID] — 격리성의 현실적 완화
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('격리성을 완화하는 이유', 'ACID 중 격리성은 실무에서 완전하게 지켜지지 않는 경우가 많습니다. 그 이유와 그로 인해 감수하는 위험을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '격리성을 완벽히 지키려면 트랜잭션들이 실제로 하나씩 순서대로 실행된 것과 같은 결과를 보장해야 하고, 이는 넓은 범위의 락이나 강한 검증을 요구합니다. 그만큼 대기가 늘어 동시 처리량이 크게 떨어지고 데드락도 잦아집니다. 대부분의 서비스는 이 비용을 감당할 수 없어 READ COMMITTED나 REPEATABLE READ 같은 중간 수준을 기본으로 씁니다. 대신 이상 현상을 감수합니다. READ COMMITTED에서는 같은 행을 다시 읽었을 때 값이 달라지는 반복 불가능한 읽기가 생길 수 있고, REPEATABLE READ에서도 조건에 맞는 새 행이 나타나는 팬텀 리드가 발생할 수 있습니다. 그래서 정확성이 특히 중요한 지점, 예컨대 재고 차감이나 잔액 갱신은 격리 수준에만 기대지 않고 비관적 락이나 낙관적 락, 원자적 갱신 쿼리 같은 수단으로 따로 보호하는 것이 일반적입니다.');
SET @e14 = LAST_INSERT_ID();

-- e15 [주 태그: 격리 수준] — 4단계 비교
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('격리 수준 네 단계 비교', '트랜잭션 격리 수준 네 단계를 낮은 것부터 설명하고, 각 단계에서 허용되는 이상 현상을 함께 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 'READ UNCOMMITTED는 커밋되지 않은 변경까지 읽을 수 있어 더티 리드가 발생합니다. 사실상 거의 쓰이지 않습니다. READ COMMITTED는 커밋된 값만 읽으므로 더티 리드는 막지만, 조회 사이에 다른 트랜잭션이 값을 바꾸면 반복 불가능한 읽기와 팬텀 리드가 생길 수 있습니다. 많은 DBMS의 기본값입니다. REPEATABLE READ는 한 트랜잭션 안에서 같은 행을 다시 읽어도 같은 값이 보이도록 보장해 반복 불가능한 읽기까지 막습니다. 표준상으로는 팬텀 리드가 남지만 MySQL InnoDB는 갭 락으로 상당 부분 막습니다. SERIALIZABLE은 트랜잭션들이 순서대로 실행된 것과 같은 결과를 보장해 모든 이상 현상을 막지만, 대기가 크게 늘어 동시 처리량이 떨어집니다. 즉 위로 갈수록 정확해지고 아래로 갈수록 빨라지는 교환 관계입니다.');
SET @e15 = LAST_INSERT_ID();

-- e16 [주 태그: 격리 수준] — 선택 기준
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('서비스에 맞는 격리 수준 고르기', '실제 서비스에서 격리 수준을 어떤 기준으로 선택해야 하는지, 무조건 높은 수준을 쓰지 않는 이유와 함께 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '기준은 그 업무가 어떤 이상 현상을 감당할 수 있는지입니다. 게시글 목록 조회처럼 잠깐 값이 달라져도 문제가 없는 작업은 READ COMMITTED로 충분합니다. 반면 한 트랜잭션 안에서 같은 데이터를 여러 번 읽어 계산에 쓰는 정산 작업이라면 중간에 값이 변하면 안 되므로 REPEATABLE READ 이상이 필요합니다. 무조건 높은 수준을 쓰지 않는 이유는 비용 때문입니다. 격리 수준이 올라갈수록 락 범위가 넓어지고 유지 기간이 길어져 대기가 늘고 데드락 위험이 커지며, 전체 처리량이 떨어집니다. 또한 격리 수준은 데이터베이스 전체나 트랜잭션 단위로 걸리는 굵은 설정이라, 특정 지점 하나 때문에 전부를 올리면 무관한 작업까지 느려집니다. 그래서 기본은 낮게 두고, 정확성이 중요한 개별 지점만 락이나 원자적 갱신으로 따로 보호하는 방식을 많이 씁니다.');
SET @e16 = LAST_INSERT_ID();

-- e17 [주 태그: 동시성 이상 현상] — 세 가지 구분
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('더티 리드, 반복 불가능한 읽기, 팬텀 리드', '동시성으로 인해 발생하는 세 가지 대표적 이상 현상을 각각 설명하고 서로 어떻게 다른지 비교하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '더티 리드는 다른 트랜잭션이 아직 커밋하지 않은 변경을 읽는 현상입니다. 그 트랜잭션이 롤백하면 존재한 적 없는 값을 읽은 셈이 되어 가장 위험합니다. 반복 불가능한 읽기는 한 트랜잭션 안에서 같은 행을 두 번 읽었는데, 그사이 다른 트랜잭션이 그 행을 수정하고 커밋해 값이 달라지는 현상입니다. 팬텀 리드는 같은 조건으로 여러 행을 조회했을 때 두 번째 조회에서 이전에 없던 행이 새로 나타나는 현상입니다. 구분하면 더티 리드는 커밋 여부의 문제이고, 반복 불가능한 읽기는 기존 행의 값이 바뀌는 문제이며, 팬텀 리드는 결과 집합에 속하는 행의 구성이 바뀌는 문제입니다. 앞의 둘은 행 단위 잠금으로 막을 수 있지만 팬텀 리드는 아직 존재하지 않는 행이 대상이라 범위 자체를 잠가야 막을 수 있어 더 비쌉니다.');
SET @e17 = LAST_INSERT_ID();

-- e18 [주 태그: 동시성 이상 현상] — 갱신 손실
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('갱신 손실이 일어나는 과정과 대응', '두 사용자가 동시에 같은 데이터를 수정할 때 발생하는 갱신 손실(Lost Update)이 어떤 과정으로 생기는지 설명하고 대응 방법을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '갱신 손실은 읽고 계산해서 다시 쓰는 흐름에서 생깁니다. 재고가 10인 상품에 두 요청이 동시에 들어와 둘 다 10을 읽고, 각자 1을 빼 9를 계산해 저장하면 두 건이 팔렸는데 재고는 9가 되어 한 건의 갱신이 사라집니다. 대응은 세 가지입니다. 첫째, 비관적 락으로 읽는 시점에 SELECT ... FOR UPDATE로 행을 잠가 다른 트랜잭션이 같은 행을 읽지 못하게 합니다. 충돌이 잦은 경우에 확실합니다. 둘째, 낙관적 락으로 버전 컬럼을 두고 갱신 시 WHERE version = ? 조건을 붙여, 갱신된 행이 없으면 충돌로 판단해 재시도합니다. 충돌이 드문 경우에 처리량이 좋습니다. 셋째, 애초에 읽지 않고 UPDATE 재고 = 재고 - 1 처럼 데이터베이스에서 원자적으로 계산하게 만드는 방법입니다. 가능하다면 이 방식이 가장 단순하고 안전합니다.');
SET @e18 = LAST_INSERT_ID();

-- e19 [주 태그: MVCC] — 동작 방식
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('MVCC의 동작 방식', 'MVCC(다중 버전 동시성 제어)가 무엇이며 어떤 방식으로 읽기와 쓰기의 충돌을 줄이는지 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 'MVCC는 하나의 행에 대해 여러 시점의 버전을 함께 유지하는 방식입니다. 행을 갱신할 때 기존 값을 덮어쓰지 않고 이전 버전을 별도 공간(InnoDB의 언두 영역)에 남긴 뒤 새 버전을 만듭니다. 각 트랜잭션은 자신이 시작한 시점을 기준으로 어떤 버전을 봐야 하는지 판단해, 그 시점에 커밋되어 있던 버전을 읽습니다. 덕분에 조회 트랜잭션은 다른 트랜잭션이 같은 행을 수정 중이어도 락을 기다리지 않고 과거 버전을 읽을 수 있고, 쓰기 트랜잭션도 읽기 때문에 막히지 않습니다. 읽기가 쓰기를 막지 않고 쓰기도 읽기를 막지 않는 것이 핵심 효과입니다. 대신 오래된 버전을 보관할 공간이 필요하고, 긴 트랜잭션이 살아 있으면 그동안 정리하지 못한 버전이 쌓여 공간이 늘어납니다. 또한 쓰기끼리의 충돌은 여전히 락으로 조정해야 합니다.');
SET @e19 = LAST_INSERT_ID();

-- e20 [주 태그: MVCC] — 락 방식과의 비교
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('MVCC와 락 기반 동시성 제어 비교', '읽기 작업을 락으로 보호하는 방식과 MVCC로 처리하는 방식을 비교하고, 각각의 장단점을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '락 기반 방식은 읽을 때 공유 락을 걸어 그 사이 다른 트랜잭션의 변경을 막습니다. 구현이 단순하고 항상 최신 값을 본다는 장점이 있지만, 조회가 많은 서비스에서는 읽기가 쓰기를 막고 쓰기가 읽기를 막아 대기가 크게 늘어납니다. MVCC는 이전 버전을 보관해 두고 조회 트랜잭션이 자신의 시점에 맞는 버전을 읽게 하므로 읽기와 쓰기가 서로를 기다리지 않습니다. 조회 비중이 높은 대부분의 웹 서비스에서 처리량이 훨씬 좋습니다. 단점도 있습니다. 버전을 보관할 공간이 필요하고 이를 정리하는 비용이 들며, 오래 열린 트랜잭션이 있으면 정리가 밀려 공간이 계속 늘어납니다. 또 조회가 보는 값이 지금 이 순간의 최신 값이 아닐 수 있어, 읽은 값을 근거로 갱신하는 로직에서는 갱신 손실을 따로 막아야 합니다. 이 경우에는 MVCC에 기대지 말고 FOR UPDATE로 명시적으로 잠그거나 버전 검사를 붙여야 합니다.');
SET @e20 = LAST_INSERT_ID();

-- e21 [주 태그: 락] — 공유 락과 배타 락
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('공유 락과 배타 락', '데이터베이스의 공유 락과 배타 락이 각각 무엇이며 서로 어떻게 양립하는지 설명하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '공유 락은 읽기를 위한 락으로, 여러 트랜잭션이 같은 자원에 동시에 걸 수 있습니다. 읽기끼리는 서로의 값을 바꾸지 않으므로 함께 진행해도 문제가 없기 때문입니다. 배타 락은 변경을 위한 락으로, 다른 어떤 락과도 함께 걸릴 수 없습니다. 이미 공유 락이 걸려 있으면 배타 락은 기다려야 하고, 배타 락이 걸려 있으면 공유 락도 기다려야 합니다. 변경 중인 중간 상태를 다른 트랜잭션이 읽어 가면 일관성이 깨지기 때문입니다. 락은 원칙적으로 트랜잭션이 커밋되거나 롤백될 때 해제됩니다. 이 규칙 때문에 조회가 대부분인 서비스에서 락만으로 동시성을 제어하면 대기가 크게 늘어나며, 그래서 많은 DBMS가 일반 조회에는 락 대신 MVCC를 사용합니다.');
SET @e21 = LAST_INSERT_ID();

-- e22 [주 태그: 락] — 락의 범위
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('락의 범위가 성능에 미치는 영향', '행 단위 락과 테이블 단위 락처럼 락의 범위가 달라질 때 생기는 차이를 성능과 안정성 측면에서 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '락 범위가 좁을수록 동시성이 높아집니다. 행 단위 락은 서로 다른 행을 다루는 트랜잭션끼리 전혀 부딪히지 않아 처리량이 좋습니다. 대신 잠근 행마다 락 정보를 관리해야 하므로 관리 비용이 들고, 한 트랜잭션이 아주 많은 행을 잠그면 그 부담이 커집니다. 그래서 일부 DBMS는 잠긴 행이 일정 수를 넘으면 상위 단위 락으로 승격시키기도 하는데, 이 경우 갑자기 넓은 범위가 잠겨 대기가 급증할 수 있습니다. 테이블 단위 락은 관리가 단순하고 대량 작업에서는 오히려 효율적이지만, 그 테이블을 쓰는 모든 트랜잭션이 멈추므로 온라인 서비스에서는 치명적입니다. 실무에서는 인덱스가 없는 컬럼을 조건으로 UPDATE하면 필요한 행만 특정하지 못해 넓은 범위가 잠기는 일이 자주 문제가 됩니다. 조건 컬럼에 적절한 인덱스를 두는 것이 락 범위를 좁게 유지하는 기본입니다.');
SET @e22 = LAST_INSERT_ID();

-- e23 [주 태그: 낙관적 락과 비관적 락] — 비교
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('낙관적 락과 비관적 락 비교', '낙관적 락과 비관적 락의 동작 방식을 비교하고, 각각 어떤 상황에 적합한지 논하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '비관적 락은 충돌이 일어날 것이라 전제하고 데이터를 읽는 시점에 미리 락을 겁니다. SELECT ... FOR UPDATE가 대표적이며, 락을 잡은 뒤에는 다른 트랜잭션이 끼어들 수 없으니 충돌 자체가 발생하지 않습니다. 대신 다른 트랜잭션이 대기하므로 처리량이 떨어지고 락을 오래 쥐면 데드락 위험도 생깁니다. 낙관적 락은 충돌이 드물 것이라 전제하고 락 없이 진행한 뒤, 갱신 시점에 버전 컬럼을 비교해 그사이 값이 바뀌었는지 확인합니다. 바뀌었으면 실패시키고 재시도합니다. 대기가 없어 처리량이 좋지만 충돌이 잦으면 재시도가 반복되어 오히려 손해입니다. 따라서 좌석 예매나 한정 수량 재고처럼 같은 행에 요청이 몰리는 경우에는 비관적 락이, 사용자가 각자 자기 데이터를 수정하는 것처럼 충돌이 드문 경우에는 낙관적 락이 적합합니다.');
SET @e23 = LAST_INSERT_ID();

-- e24 [주 태그: 낙관적 락과 비관적 락] — 낙관적 락 구현
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('낙관적 락의 구현과 재시도 설계', '버전 컬럼을 이용한 낙관적 락이 어떻게 충돌을 감지하는지 설명하고, 충돌이 발생했을 때의 처리 방식을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '엔티티에 version 컬럼을 두고, 조회할 때 그 값을 함께 읽습니다. 갱신할 때는 UPDATE ... SET value = ?, version = version + 1 WHERE id = ? AND version = 읽은값 형태로 조건을 붙입니다. 그사이 다른 트랜잭션이 같은 행을 갱신했다면 version이 이미 올라가 있어 조건에 맞는 행이 없고, 영향받은 행 수가 0이 됩니다. 이를 충돌로 판단합니다. JPA에서는 @Version 애너테이션으로 같은 동작을 자동화하며 충돌 시 예외를 던집니다. 충돌 처리 방식은 상황에 따라 다릅니다. 사용자 입력이 개입하지 않는 계산이라면 최신 값을 다시 읽어 자동으로 재시도하는 것이 자연스럽습니다. 이때 재시도 횟수에 상한을 두고, 계속 실패하면 포기하도록 해야 무한 반복을 막을 수 있습니다. 반대로 사용자가 화면에서 편집한 내용을 저장하는 경우라면 임의로 덮어쓰지 말고, 다른 사람이 먼저 수정했음을 알리고 판단을 맡기는 편이 안전합니다.');
SET @e24 = LAST_INSERT_ID();

-- e25 [주 태그: 트랜잭션 데드락] — 발생 조건
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('데드락이 생기는 조건과 예방', '데이터베이스에서 데드락이 발생하는 과정을 예를 들어 설명하고, 예방하거나 줄이는 방법을 논하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '데드락은 두 트랜잭션이 서로가 쥔 자원을 기다리며 둘 다 진행하지 못하는 상태입니다. 예를 들어 트랜잭션 A가 1번 행을 잠근 뒤 2번 행을 잠그려 하고, 같은 시각 트랜잭션 B가 2번 행을 잠근 뒤 1번 행을 잠그려 하면 서로를 영원히 기다립니다. 예방과 완화 방법은 다음과 같습니다. 첫째, 모든 트랜잭션이 자원을 같은 순서로 잠그도록 규칙을 정합니다. 순환 대기가 만들어지지 않아 근본적으로 막을 수 있습니다. 둘째, 트랜잭션 범위를 짧게 유지해 락을 쥐는 시간을 줄입니다. 셋째, 조건 컬럼에 인덱스를 두어 필요한 행만 잠기게 합니다. 넷째, 락 대기 시간에 타임아웃을 두어 오래 매달리지 않게 합니다. 대부분의 DBMS는 데드락을 감지하면 한쪽을 희생자로 골라 롤백시켜 순환을 끊으므로, 애플리케이션은 그 예외를 잡아 재시도할 수 있도록 만들어 두는 것이 좋습니다.');
SET @e25 = LAST_INSERT_ID();

-- e26 [주 태그: 트랜잭션 데드락] — 감지와 대응
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('데드락 감지 이후의 대응', 'DBMS가 데드락을 감지했을 때 어떻게 처리하는지 설명하고, 애플리케이션은 이에 어떻게 대응해야 하는지 서술하시오.', 'ESSAY', 'HIGH', 'DB',
 'DBMS는 어떤 트랜잭션이 어떤 자원을 기다리는지를 그래프로 관리하다가 순환이 생기면 데드락으로 판단합니다. 순환은 저절로 풀리지 않으므로 한쪽을 희생자로 선택해 강제로 롤백시킵니다. 선택 기준은 구현마다 다르지만 대체로 되돌릴 작업이 적은, 즉 변경량이 작은 트랜잭션을 고릅니다. 희생된 트랜잭션은 오류를 받고 종료되며, 살아남은 쪽은 기다리던 락을 얻어 진행합니다. 애플리케이션은 이 오류를 예상 가능한 상황으로 다뤄야 합니다. 데드락 예외를 잡아 일정 횟수까지 재시도하되, 매번 같은 순서로 부딪히지 않도록 짧은 무작위 대기를 두는 것이 좋습니다. 다만 재시도는 증상 완화일 뿐이므로, 로그로 어떤 쿼리들이 부딪히는지 확인해 잠금 순서를 통일하거나 트랜잭션을 쪼개는 근본 대응을 병행해야 합니다.');
SET @e26 = LAST_INSERT_ID();

-- e27 [주 태그: 트랜잭션 전파] — 전파 속성
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('트랜잭션 전파 속성', '트랜잭션 전파(Propagation)가 무엇인지 설명하고, REQUIRED와 REQUIRES_NEW의 차이를 예를 들어 서술하시오.', 'ESSAY', 'HIGH', 'DB',
 '전파는 트랜잭션이 이미 진행 중인 상태에서 다른 트랜잭션 경계를 가진 메서드를 호출했을 때 어떻게 처리할지를 정하는 규칙입니다. REQUIRED는 기본값으로, 진행 중인 트랜잭션이 있으면 그것에 합류하고 없으면 새로 시작합니다. 합류한 경우 하나의 트랜잭션이므로 안쪽에서 예외가 나면 바깥까지 함께 롤백됩니다. REQUIRES_NEW는 진행 중인 트랜잭션을 잠시 보류하고 완전히 독립된 새 트랜잭션을 시작합니다. 두 트랜잭션은 서로 영향을 주지 않아, 안쪽이 롤백해도 바깥은 계속 진행할 수 있고 바깥이 롤백해도 이미 커밋된 안쪽은 되돌아가지 않습니다. 주문 처리 중 이력 로그를 남기는 경우가 대표적입니다. 주문이 실패해도 시도했다는 기록은 남겨야 한다면 로그 저장을 REQUIRES_NEW로 둡니다. 다만 REQUIRES_NEW는 커넥션을 하나 더 점유하므로 남용하면 커넥션 풀이 고갈될 수 있고, 바깥 트랜잭션이 잠근 행을 안쪽에서 다시 잠그려 하면 스스로를 기다리는 교착에 빠질 수 있어 주의해야 합니다.');
SET @e27 = LAST_INSERT_ID();

-- e28 [주 태그: 트랜잭션 전파] — 자기 호출 문제
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('같은 클래스 내부 호출에서 트랜잭션이 걸리지 않는 이유', '스프링에서 같은 클래스의 다른 메서드를 직접 호출하면 그 메서드의 트랜잭션 설정이 적용되지 않는 이유를 설명하고, 해결 방법을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '스프링의 선언적 트랜잭션은 프록시를 통해 동작합니다. 컨테이너는 대상 객체를 감싼 프록시를 만들어 빈으로 등록하고, 외부에서 프록시의 메서드를 호출하면 프록시가 트랜잭션을 시작한 뒤 실제 객체의 메서드를 호출합니다. 그런데 클래스 내부에서 this로 다른 메서드를 부르면 프록시를 거치지 않고 실제 객체의 메서드가 곧바로 실행됩니다. 트랜잭션을 시작할 지점이 없으니 애너테이션이 무시되고, 전파 속성도 적용되지 않습니다. 해결 방법은 몇 가지가 있습니다. 가장 깔끔한 것은 해당 메서드를 별도의 빈으로 분리해 주입받아 호출하는 것입니다. 호출이 프록시를 거치게 되어 정상 동작합니다. 자기 자신을 주입받아 프록시를 통해 호출하는 방법도 있지만 순환 참조를 다뤄야 해 권장되지 않습니다. AOP 방식을 프록시가 아닌 바이트코드 조작으로 바꾸면 내부 호출도 잡히지만 설정 부담이 큽니다. 대개는 책임을 분리하는 첫 번째 방법이 설계상으로도 낫습니다.');
SET @e28 = LAST_INSERT_ID();

-- e29 [주 태그: 커넥션 풀] — 필요성
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('커넥션 풀이 필요한 이유', '애플리케이션에서 데이터베이스 커넥션 풀을 사용하는 이유를 커넥션 생성 비용과 부하 제어 관점에서 설명하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '데이터베이스 커넥션은 TCP 연결을 맺고 인증을 거쳐 세션을 준비하는 과정을 포함해 만드는 비용이 큽니다. 요청마다 새로 연결하면 이 비용이 매번 발생해 응답 시간이 크게 늘어납니다. 커넥션 풀은 미리 일정 개수의 커넥션을 만들어 두고 요청이 오면 빌려주었다가 반납받아 재사용함으로써 이 비용을 없앱니다. 또 하나의 중요한 역할은 부하 제어입니다. 풀 크기가 곧 동시에 데이터베이스를 쓸 수 있는 요청 수의 상한이 되므로, 트래픽이 몰려도 데이터베이스로 넘어가는 동시 요청이 그 이상으로 늘어나지 않습니다. 상한이 없으면 데이터베이스가 과도한 동시 연결로 먼저 무너지는데, 풀은 앞단에서 대기시켜 이를 막습니다. 그래서 풀 크기는 무작정 크게 잡는 것이 아니라 데이터베이스가 감당할 수 있는 수준에 맞춰 정해야 합니다.');
SET @e29 = LAST_INSERT_ID();

-- e30 [주 태그: 커넥션 풀] — 크기 산정과 고갈
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('커넥션 풀 고갈과 크기 산정', '커넥션 풀이 고갈되면 어떤 증상이 나타나는지 설명하고, 풀 크기를 정할 때 고려해야 할 점을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '풀이 고갈되면 커넥션을 얻지 못한 요청이 대기하다가 획득 타임아웃으로 실패합니다. 증상은 특정 쿼리가 느린 것이 아니라 서비스 전반의 응답이 함께 느려지고, 로그에는 커넥션 획득 실패 예외가 몰려 나타납니다. 데이터베이스 자체는 한가한데 애플리케이션만 밀리는 형태가 전형적입니다. 원인은 대개 커넥션을 오래 쥐는 코드입니다. 트랜잭션 안에서 외부 API를 호출하거나 대량 조회를 하는 경우가 흔합니다. 크기를 정할 때는 먼저 데이터베이스가 감당 가능한 최대 연결 수를 확인하고, 애플리케이션 인스턴스 수를 곱한 값이 그 한계를 넘지 않게 해야 합니다. 그다음 평균 쿼리 처리 시간과 목표 처리량으로 필요한 동시 커넥션 수를 추정합니다. 크기를 키우는 것이 항상 답은 아닙니다. 데이터베이스의 CPU와 디스크가 한계라면 커넥션만 늘려도 경합만 심해져 전체가 느려집니다. 오히려 느린 쿼리를 고치고 트랜잭션 범위를 줄이는 편이 근본적인 해결입니다.');
SET @e30 = LAST_INSERT_ID();

-- e31 [주 태그: 정규화] — 목적과 이상 현상
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('정규화와 이상 현상', '정규화가 해결하려는 이상 현상 세 가지를 예를 들어 설명하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '정규화는 중복을 제거하고 속성을 관련 있는 테이블로 분리하는 과정이며, 이를 통해 세 가지 이상 현상을 막습니다. 삽입 이상은 새 데이터를 넣고 싶은데 아직 알 수 없는 다른 값까지 함께 넣어야 하는 문제입니다. 학생과 수강 과목을 한 테이블에 두면 아직 수강 신청을 하지 않은 학생을 등록할 수 없습니다. 갱신 이상은 같은 값이 여러 행에 중복 저장되어 있어 일부만 수정되면 데이터가 서로 어긋나는 문제입니다. 학과 사무실 전화번호가 학생 행마다 들어 있으면 번호가 바뀌었을 때 모든 행을 빠짐없이 고쳐야 합니다. 삭제 이상은 한 정보를 지우면 함께 저장된 다른 정보까지 사라지는 문제입니다. 마지막 수강 기록을 지웠더니 그 학생 정보 자체가 없어지는 경우입니다. 세 문제 모두 서로 다른 성격의 정보가 한 테이블에 섞여 있어 생기며, 의존 관계에 따라 테이블을 분리하면 해소됩니다.');
SET @e31 = LAST_INSERT_ID();

-- e32 [주 태그: 정규화] — 정규형 단계
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('제1정규형부터 제3정규형까지', '제1정규형, 제2정규형, 제3정규형이 각각 무엇을 요구하는지 설명하고 단계별로 무엇이 해소되는지 서술하시오.', 'ESSAY', 'HIGH', 'DB',
 '제1정규형은 모든 속성이 더 이상 나눌 수 없는 단일 값을 가져야 한다는 조건입니다. 한 칸에 전화번호를 쉼표로 여러 개 넣거나 반복 그룹 컬럼을 두면 위반이며, 값을 행으로 분리해 해소합니다. 제2정규형은 제1정규형을 만족하면서 기본 키의 일부에만 의존하는 속성이 없어야 한다는 조건입니다. 복합 키를 쓸 때만 문제가 되며, 예를 들어 (주문번호, 상품번호)가 키인 테이블에 상품명이 들어 있으면 상품명은 상품번호에만 의존하므로 부분 함수 종속입니다. 상품 테이블로 분리해 해소합니다. 제3정규형은 제2정규형을 만족하면서 키가 아닌 속성이 다른 키 아닌 속성에 의존하지 않아야 한다는 조건입니다. 학생 테이블에 학과코드와 학과명이 함께 있으면 학과명은 학과코드에 의존하므로 이행적 종속입니다. 학과 테이블로 분리합니다. 단계가 올라갈수록 중복이 줄어 이상 현상이 사라지지만 테이블 수와 조인이 늘어납니다.');
SET @e32 = LAST_INSERT_ID();

-- e33 [주 태그: 반정규화] — 목적과 대가
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('반정규화의 목적과 대가', '반정규화를 적용하는 목적과 그 대가를 설명하고, 어떤 기준으로 적용 여부를 판단해야 하는지 논하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '반정규화는 정규화로 나뉜 테이블에 중복을 의도적으로 허용해 조인을 줄이고 조회 성능을 얻는 기법입니다. 게시글 목록에서 매번 댓글 테이블을 집계하는 대신 게시글에 댓글 수 컬럼을 두는 것이 대표적입니다. 대가는 정합성 관리 부담입니다. 같은 값이 두 곳에 존재하므로 댓글이 추가되거나 삭제될 때마다 카운트를 반드시 함께 갱신해야 하고, 어느 한쪽만 반영되는 순간 데이터가 어긋납니다. 쓰기 비용도 늘어납니다. 판단 기준은 명확합니다. 먼저 정규화된 구조를 기본으로 두고, 실행 계획과 실제 측정으로 병목이 확인된 지점에 한해 적용합니다. 그다음 그 지점의 읽기와 쓰기 비율을 봅니다. 읽기가 압도적으로 많아야 이득이 있습니다. 마지막으로 정합성을 어떻게 보장할지 방법을 먼저 정해 두어야 합니다. 갱신을 한 트랜잭션으로 묶을지, 주기적으로 다시 계산해 맞출지를 결정하지 않은 채 컬럼만 추가하면 시간이 지나며 값이 틀어집니다.');
SET @e33 = LAST_INSERT_ID();

-- e34 [주 태그: 반정규화] — 정합성 유지
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('반정규화한 데이터의 정합성 유지', '집계 값을 별도 컬럼으로 두는 반정규화를 적용했을 때 그 값의 정합성을 유지하는 방법들을 비교하시오.', 'ESSAY', 'HIGH', 'DB',
 '첫째, 원본 변경과 집계 갱신을 같은 트랜잭션으로 묶는 방법입니다. 가장 확실하지만 같은 행을 여러 요청이 동시에 갱신하면 락 경합이 생기고, 인기 게시글처럼 트래픽이 몰리는 대상에서는 병목이 됩니다. 둘째, 데이터베이스 트리거로 자동 갱신하는 방법입니다. 애플리케이션이 빠뜨릴 여지가 없지만 로직이 데이터베이스에 숨어 있어 추적과 테스트가 어렵습니다. 셋째, 이벤트를 발행해 비동기로 갱신하는 방법입니다. 원본 처리가 빨라지고 부하가 분산되지만 잠시 값이 맞지 않는 구간이 생기며, 이벤트 유실에 대비한 재처리 장치가 필요합니다. 넷째, 주기적으로 원본에서 다시 계산해 덮어쓰는 보정 작업입니다. 위 방법 중 무엇을 쓰든 어긋남은 결국 생기므로, 보정 배치는 함께 두는 것이 안전합니다. 실무에서는 값이 잠깐 부정확해도 되는지에 따라 갈립니다. 잔액처럼 정확해야 하면 같은 트랜잭션으로 묶고, 조회수처럼 근사해도 되면 비동기 갱신과 주기적 보정을 조합합니다.');
SET @e34 = LAST_INSERT_ID();

-- e35 [주 태그: 키와 제약조건] — 키의 종류
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('기본 키, 후보 키, 외래 키', '기본 키와 후보 키, 외래 키가 각각 무엇인지 설명하고 서로 어떤 관계에 있는지 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '후보 키는 테이블의 행을 유일하게 식별할 수 있는 속성 또는 속성 조합으로, 불필요한 속성이 포함되지 않은 최소 단위여야 합니다. 한 테이블에 여러 개 존재할 수 있습니다. 회원 테이블이라면 회원번호, 이메일, 주민등록번호가 모두 후보 키가 될 수 있습니다. 기본 키는 후보 키 중에서 대표로 선택한 하나입니다. 테이블당 하나만 두며 NULL을 허용하지 않습니다. 선택되지 않은 나머지 후보 키는 대체 키라 부르며 보통 유니크 제약으로 표현합니다. 외래 키는 다른 테이블의 기본 키(또는 유니크한 값)를 참조하는 속성으로, 두 테이블 사이의 관계를 나타내며 참조 무결성을 보장합니다. 참조하는 값이 실제로 존재해야 하고, 참조되는 행을 지우거나 바꿀 때 어떻게 처리할지를 CASCADE나 RESTRICT 같은 옵션으로 정합니다. 정리하면 후보 키 중 하나가 기본 키가 되고, 그 기본 키를 다른 테이블에서 가리키는 것이 외래 키입니다.');
SET @e35 = LAST_INSERT_ID();

-- e36 [주 태그: 키와 제약조건] — 자연 키와 대리 키
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('자연 키와 대리 키의 선택', '업무상 의미가 있는 값을 기본 키로 쓰는 것과 의미 없는 일련번호를 기본 키로 두는 것을 비교하고, 어느 쪽을 권하는지 근거와 함께 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '자연 키는 이메일이나 사업자등록번호처럼 업무상 의미가 있는 값을 기본 키로 쓰는 방식입니다. 별도 컬럼이 필요 없고 키 자체가 정보를 담아 조인 없이 값을 알 수 있다는 장점이 있습니다. 문제는 변경 가능성입니다. 이메일은 바뀔 수 있고, 업무 규칙이 달라져 형식이 변하기도 합니다. 기본 키가 바뀌면 그 값을 참조하던 모든 외래 키를 함께 고쳐야 해 파급이 큽니다. 또 길이가 길면 모든 보조 인덱스가 함께 커지고, 개인정보가 키로 여기저기 퍼지는 문제도 있습니다. 대리 키는 업무와 무관한 일련번호를 두는 방식으로, 절대 바뀌지 않고 짧아 인덱스 효율이 좋습니다. 대신 컬럼이 하나 늘고 그 값만으로는 의미를 알 수 없습니다. 일반적으로는 대리 키를 기본 키로 두고, 자연 키에는 유니크 제약을 걸어 유일성을 보장하는 조합을 권합니다. 식별의 안정성과 업무 규칙의 강제를 분리해 각각 지킬 수 있기 때문입니다.');
SET @e36 = LAST_INSERT_ID();

-- e37 [주 태그: NULL 처리] — 비교와 집계
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('NULL이 비교와 집계에서 동작하는 방식', 'SQL에서 NULL이 비교 연산자와 집계 함수에서 어떻게 다뤄지는지 설명하고 주의할 점을 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 'NULL은 값이 없다가 아니라 값을 알 수 없다는 뜻이며, SQL은 이를 참도 거짓도 아닌 제3의 논리값으로 다룹니다. 그래서 컬럼 = NULL 이나 컬럼 <> NULL 은 어떤 행도 반환하지 않으며 IS NULL, IS NOT NULL을 써야 합니다. NULL끼리 비교해도 같다는 결과가 나오지 않습니다. 집계 함수는 COUNT(*)를 제외하고 NULL인 행을 계산에서 제외합니다. COUNT(컬럼)은 그 컬럼이 NULL이 아닌 행만 세고, SUM과 AVG도 NULL을 빼고 계산하므로 AVG의 분모가 전체 행 수와 달라질 수 있습니다. 주의할 점이 몇 가지 더 있습니다. NOT IN 서브쿼리 결과에 NULL이 하나라도 있으면 전체가 아무 행도 반환하지 않는 함정이 있어 NOT EXISTS를 쓰는 편이 안전합니다. 문자열 연결이나 산술 연산에서 NULL이 섞이면 결과 전체가 NULL이 되므로 COALESCE나 IFNULL로 기본값을 정해 주어야 합니다. 정렬 시 NULL의 위치도 DBMS마다 다릅니다.');
SET @e37 = LAST_INSERT_ID();

-- e38 [주 태그: NULL 처리] — 설계 관점
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('NULL을 허용할지 결정하기', '테이블을 설계할 때 컬럼에 NULL을 허용할지 결정하는 기준을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '기본 원칙은 NULL을 최대한 줄이는 것입니다. NULL은 비교와 집계에서 특수하게 동작해 쿼리를 복잡하게 만들고, 개발자가 그 규칙을 잊으면 조용히 잘못된 결과를 냅니다. 다만 무조건 금지하는 것도 옳지 않습니다. 판단 기준은 그 값이 실제로 없을 수 있는지입니다. 값이 아직 정해지지 않았거나 해당 사항이 없는 경우, 예컨대 탈퇴일이나 중간 이름처럼 진짜로 존재하지 않는 값이라면 NULL이 자연스럽습니다. 이때 억지로 빈 문자열이나 0, 9999-12-31 같은 가짜 값을 넣으면 없음과 실제 값이 구분되지 않아 더 위험합니다. 반대로 항상 존재해야 하는 값이라면 NOT NULL과 기본값을 함께 지정합니다. 또 하나의 신호는 특정 조건에서만 채워지는 컬럼이 많다는 점입니다. 이는 성격이 다른 개체를 한 테이블에 억지로 담고 있다는 뜻일 수 있어, 테이블 분리를 검토하는 편이 낫습니다. 즉 NULL 허용 여부는 단순한 옵션이 아니라 그 컬럼이 정말 그 테이블에 속하는지를 되묻는 설계 질문입니다.');
SET @e38 = LAST_INSERT_ID();

-- e39 [주 태그: RDB와 NoSQL] — 비교
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('관계형 데이터베이스와 NoSQL 비교', '관계형 데이터베이스와 NoSQL의 차이를 데이터 모델, 확장 방식, 트랜잭션 보장 측면에서 비교하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '데이터 모델 측면에서 관계형 데이터베이스는 미리 정의한 스키마에 따라 행과 열로 데이터를 저장하고, 테이블을 나눈 뒤 조인으로 합쳐 봅니다. NoSQL은 문서, 키-값, 컬럼 패밀리, 그래프 등 목적에 맞는 모델을 쓰며 스키마가 유연해 형태가 제각각인 데이터도 담을 수 있습니다. 확장 방식에서 관계형 데이터베이스는 전통적으로 서버 성능을 키우는 수직 확장에 의존하며, 수평 확장은 샤딩 등으로 가능하지만 조인과 트랜잭션 때문에 복잡합니다. NoSQL은 처음부터 여러 노드에 데이터를 나눠 담는 수평 확장을 전제로 설계된 경우가 많습니다. 트랜잭션 보장에서 관계형 데이터베이스는 여러 테이블에 걸친 ACID를 강하게 제공합니다. NoSQL은 단일 문서나 단일 키 범위에서는 원자성을 보장하지만 그 범위를 넘어서면 제한적이며, 대신 가용성과 응답성을 우선해 최종적 일관성을 택하는 경우가 많습니다. 요약하면 정형화된 데이터와 강한 정합성이 필요하면 관계형, 유연한 구조와 대규모 확장이 필요하면 NoSQL이 유리합니다.');
SET @e39 = LAST_INSERT_ID();

-- e40 [주 태그: RDB와 NoSQL] — 선택 판단
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('저장소를 고를 때의 판단 기준', '새 서비스를 만들 때 관계형 데이터베이스와 NoSQL 중 무엇을 쓸지 판단하는 기준을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '먼저 데이터의 형태와 관계를 봅니다. 주문과 상품, 회원처럼 개체 사이의 관계가 뚜렷하고 여러 관점으로 조회해야 한다면 관계형이 맞습니다. 조회 패턴이 하나로 정해져 있고 문서 단위로 통째로 읽고 쓰는 형태라면 문서 데이터베이스가 편합니다. 다음으로 정합성 요구를 봅니다. 결제나 재고처럼 여러 테이블의 갱신이 함께 성공해야 한다면 관계형의 트랜잭션이 필요합니다. 세 번째로 규모와 증가 속도를 봅니다. 로그나 이벤트처럼 양이 폭발적으로 늘고 한 대에 담기 어려우면 수평 확장에 강한 저장소를 고려합니다. 네 번째로 팀의 운영 역량을 봅니다. 익숙하지 않은 저장소는 장애 대응과 백업, 모니터링에서 비용이 큽니다. 현실적인 조언을 덧붙이면, 초기에는 관계형으로 시작하는 편이 안전합니다. 요구가 아직 확정되지 않은 단계에서는 스키마와 조인이 오히려 변경을 흡수해 주고, 규모가 실제로 커진 뒤 병목이 확인된 영역만 다른 저장소로 옮기는 편이 낫습니다. 하나만 고르는 문제로 볼 필요도 없습니다.');
SET @e40 = LAST_INSERT_ID();

-- e41 [주 태그: 조인] — 종류 비교
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('조인 종류와 결과 차이', 'INNER JOIN, LEFT OUTER JOIN, FULL OUTER JOIN이 각각 어떤 결과를 만드는지 비교하고, 어떤 상황에 무엇을 써야 하는지 설명하시오.', 'ESSAY', 'MEDIUM', 'DB',
 'INNER JOIN은 조인 조건을 만족하는 행만 남깁니다. 양쪽 모두에 짝이 있는 데이터만 필요할 때 씁니다. 결제가 완료된 주문만 보고 싶다면 주문과 결제를 INNER JOIN 합니다. LEFT OUTER JOIN은 왼쪽 테이블의 행을 모두 남기고 오른쪽에 짝이 없으면 그 컬럼들을 NULL로 채웁니다. 기준이 되는 집합을 빠짐없이 보되 부가 정보를 덧붙이고 싶을 때 씁니다. 모든 주문을 나열하면서 결제 여부를 함께 보는 경우입니다. 여기에 오른쪽 컬럼이 NULL인 조건을 추가하면 짝이 없는 행만 골라낼 수도 있어, 아직 결제되지 않은 주문을 찾는 데 유용합니다. FULL OUTER JOIN은 양쪽 모두의 행을 남기고 짝이 없는 쪽을 NULL로 채웁니다. 두 집합의 차이를 양방향으로 확인하는 데이터 검증 작업에 주로 쓰며, MySQL은 직접 지원하지 않아 LEFT와 RIGHT 결과를 UNION으로 합쳐 흉내 냅니다. 주의할 점은 OUTER JOIN에서 오른쪽 테이블에 대한 조건을 WHERE에 두면 NULL 행이 걸러져 사실상 INNER JOIN이 된다는 것입니다. 그런 조건은 ON 절에 두어야 합니다.');
SET @e41 = LAST_INSERT_ID();

-- e42 [주 태그: 조인] — 조인 성능
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('조인 성능에 영향을 주는 요소', '조인이 포함된 쿼리의 성능에 영향을 주는 요소들을 설명하고, 느린 조인을 개선하는 방법을 논하시오.', 'ESSAY', 'HIGH', 'DB',
 '가장 중요한 것은 조인 키에 인덱스가 있는지입니다. 인덱스가 없으면 한쪽 행마다 상대 테이블을 전부 훑어야 해 비용이 급격히 커집니다. 다음은 조인 순서입니다. 결과를 크게 줄이는 조건이 걸린 테이블을 먼저 처리해 중간 결과를 작게 유지해야 이후 단계가 가벼워집니다. 옵티마이저가 순서를 정하지만 통계가 부정확하면 잘못 고를 수 있습니다. 세 번째는 조인 방식입니다. 한쪽이 작으면 그 결과를 기준으로 상대를 인덱스로 찾아가는 방식이 유리하고, 양쪽이 모두 크면 해시나 정렬 기반 방식이 나을 수 있습니다. 네 번째는 중간 결과 크기입니다. 일대다 관계를 여러 번 조인하면 행이 곱으로 불어나 정렬과 집계 비용이 폭증합니다. 개선 방법으로는 조인 키 인덱스 확인, 필터 조건을 가능한 한 먼저 적용해 대상 행 줄이기, 필요한 컬럼만 선택하기, 행이 불어나는 다중 조인은 서브쿼리로 미리 집계한 뒤 조인하기, 그리고 조회 전용 화면이라면 반정규화를 검토하는 순서로 접근합니다.');
SET @e42 = LAST_INSERT_ID();

-- e43 [주 태그: 서브쿼리] — 종류와 용도
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('서브쿼리의 종류와 쓰임', 'SQL에서 서브쿼리가 쓰이는 위치에 따라 어떻게 나뉘는지 설명하고 각각의 용도를 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '위치에 따라 크게 셋으로 나뉩니다. WHERE 절 서브쿼리는 조건을 만들기 위해 쓰며, 평균보다 비싼 상품을 찾는 것처럼 다른 집합의 결과를 조건으로 삼을 때 사용합니다. IN, EXISTS, 비교 연산자와 함께 쓰입니다. FROM 절 서브쿼리는 인라인 뷰라 부르며, 미리 가공하거나 집계한 결과를 하나의 임시 테이블처럼 다뤄 다시 조인하거나 필터링할 때 씁니다. 카테고리별 평균을 먼저 구한 뒤 원본과 조인해 비교하는 경우가 대표적입니다. SELECT 절 서브쿼리는 스칼라 서브쿼리라 하며 각 행마다 하나의 값을 계산해 컬럼처럼 붙입니다. 반드시 단일 값을 반환해야 합니다. 또 다른 구분으로 바깥 쿼리의 컬럼을 참조하는지에 따라 상관 서브쿼리와 비상관 서브쿼리로 나눕니다. 비상관 서브쿼리는 한 번만 평가해 재사용할 수 있지만 상관 서브쿼리는 바깥 행마다 다시 평가될 수 있어 비용이 큽니다.');
SET @e43 = LAST_INSERT_ID();

-- e44 [주 태그: 서브쿼리] — 조인으로의 변환
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('서브쿼리를 조인으로 바꿔야 할 때', '서브쿼리를 조인으로 바꾸면 성능이 좋아지는 경우와, 굳이 바꾸지 않아도 되는 경우를 구분해 설명하시오.', 'ESSAY', 'HIGH', 'DB',
 '바꾸면 좋아지는 대표적인 경우는 바깥 행마다 반복 평가되는 상관 서브쿼리입니다. 특히 SELECT 절의 스칼라 서브쿼리로 각 행에 연관 값을 붙이는 형태는 행 수만큼 조회가 반복되므로, 한 번의 조인으로 바꾸면 접근 횟수가 크게 줄어듭니다. WHERE 절의 IN 서브쿼리도 대상 집합이 크면 조인이나 EXISTS로 바꾸는 편이 유리한 경우가 많습니다. 반대로 굳이 바꾸지 않아도 되는 경우도 많습니다. 최신 옵티마이저는 단순한 형태의 서브쿼리를 내부적으로 조인으로 변환해 처리하므로 이미 같은 계획으로 실행되고 있을 수 있습니다. 또 EXISTS는 조건을 만족하는 행을 하나만 찾으면 즉시 멈추므로, 존재 여부만 확인하는 목적이라면 조인보다 오히려 효율적입니다. 조인으로 바꿀 때 일대다 관계에서 결과 행이 중복돼 DISTINCT를 붙이게 되면 정렬 비용이 추가되어 손해를 볼 수도 있습니다. 결론적으로 형태만 보고 기계적으로 바꾸지 말고, 실행 계획으로 반복 평가가 실제로 일어나는지 확인한 뒤 판단해야 합니다.');
SET @e44 = LAST_INSERT_ID();

-- e45 [주 태그: 집계와 GROUP BY] — 처리 순서
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('GROUP BY 쿼리의 처리 순서', 'WHERE, GROUP BY, HAVING, ORDER BY가 포함된 쿼리가 어떤 순서로 처리되는지 설명하고, 이 순서를 아는 것이 왜 중요한지 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 '논리적 처리 순서는 FROM과 JOIN으로 대상 집합을 만들고, WHERE로 개별 행을 걸러낸 뒤, GROUP BY로 묶고, 집계 함수를 계산하고, HAVING으로 그룹을 걸러내고, SELECT 목록을 만들고, ORDER BY로 정렬한 다음 LIMIT으로 잘라내는 순서입니다. 이 순서를 알아야 하는 이유는 세 가지입니다. 첫째, WHERE에서는 집계 함수를 쓸 수 없습니다. 아직 집계가 이뤄지지 않은 단계이기 때문이며, 집계 결과로 거르려면 HAVING을 써야 합니다. 둘째, 성능이 달라집니다. 집계와 무관한 조건을 HAVING에 두면 불필요한 행까지 묶어 집계한 뒤 버리게 되므로, 가능한 조건은 WHERE에서 먼저 걸러 대상 행을 줄여야 합니다. 셋째, SELECT에서 붙인 별칭을 어디서 쓸 수 있는지가 결정됩니다. SELECT는 HAVING보다 뒤에 처리되므로 표준상 HAVING에서는 별칭을 쓸 수 없고, ORDER BY는 SELECT 뒤에 오므로 별칭을 쓸 수 있습니다. 다만 이는 논리적 순서이며 실제 실행은 옵티마이저가 결과가 같은 범위에서 다르게 최적화할 수 있습니다.');
SET @e45 = LAST_INSERT_ID();

-- e46 [주 태그: 집계와 GROUP BY] — 집계 함수와 NULL
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('COUNT(*)와 COUNT(컬럼)의 차이', 'COUNT(*), COUNT(컬럼), COUNT(DISTINCT 컬럼)의 차이를 설명하고 집계 함수를 쓸 때 주의할 점을 서술하시오.', 'ESSAY', 'MEDIUM', 'DB',
 'COUNT(*)는 조건을 만족하는 행의 개수를 셉니다. 특정 컬럼의 값과 무관하므로 NULL이 있어도 그대로 세어집니다. COUNT(컬럼)은 그 컬럼이 NULL이 아닌 행만 셉니다. 따라서 NULL이 섞인 컬럼에서는 COUNT(*)보다 작은 값이 나오며, 이 차이를 모르고 쓰면 결과가 조용히 달라집니다. COUNT(DISTINCT 컬럼)은 NULL을 제외한 뒤 중복을 제거하고 남은 값의 종류를 셉니다. 중복 제거를 위해 정렬이나 해시 작업이 필요해 비용이 더 큽니다. 주의할 점을 덧붙이면, SUM과 AVG도 NULL을 계산에서 제외하므로 AVG는 분모가 전체 행 수가 아니라 값이 있는 행 수가 됩니다. NULL을 0으로 취급하고 싶다면 COALESCE로 먼저 변환해야 합니다. 또 집계 대상이 하나도 없을 때 COUNT는 0을 반환하지만 SUM은 0이 아니라 NULL을 반환하므로, 이 값을 그대로 계산에 쓰면 결과 전체가 NULL이 되는 함정이 있습니다. GROUP BY와 함께 쓸 때 그룹에 포함되지 않은 컬럼을 SELECT에 넣으면 표준상 오류이며, 허용하는 DBMS라도 임의의 값이 나오므로 피해야 합니다.');
SET @e46 = LAST_INSERT_ID();

-- e47 [주 태그: ORM과 영속성 컨텍스트] — 역할
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('영속성 컨텍스트가 하는 일', 'JPA의 영속성 컨텍스트가 어떤 역할을 하는지 설명하고, 그로 인해 얻는 이점을 서술하시오.', 'ESSAY', 'HIGH', 'DB',
 '영속성 컨텍스트는 엔티티를 보관하고 관리하는 논리적 공간으로, 보통 트랜잭션 범위와 생명주기를 같이합니다. 하는 일은 크게 넷입니다. 첫째, 1차 캐시입니다. 같은 식별자로 다시 조회하면 데이터베이스에 가지 않고 보관 중인 엔티티를 그대로 반환합니다. 덕분에 한 트랜잭션 안에서 같은 엔티티는 항상 동일한 인스턴스임이 보장되어 == 비교가 성립합니다. 둘째, 변경 감지입니다. 엔티티를 읽어 온 시점의 스냅샷을 보관해 두었다가 플러시 시점에 현재 값과 비교해 달라진 필드가 있으면 UPDATE를 만들어 냅니다. 별도의 저장 호출이 필요 없습니다. 셋째, 쓰기 지연입니다. 등록이나 수정 쿼리를 곧바로 보내지 않고 모아 두었다가 플러시 때 한 번에 내보내 왕복을 줄입니다. 넷째, 지연 로딩을 위한 프록시 관리입니다. 이점은 불필요한 조회 감소와 객체 동일성 보장이지만, 반대로 관리 대상이 많아지면 메모리 사용과 비교 비용이 늘어나므로 대량 처리에서는 주기적으로 비워 주어야 합니다.');
SET @e47 = LAST_INSERT_ID();

-- e48 [주 태그: ORM과 영속성 컨텍스트] — 한계
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('ORM을 쓸 때 주의해야 할 점', 'ORM을 사용할 때 발생하기 쉬운 문제들을 설명하고, 어떤 자세로 사용해야 하는지 논하시오.', 'ESSAY', 'HIGH', 'DB',
 'ORM은 객체와 테이블의 차이를 메워 주지만 데이터베이스를 감춰 주지는 않습니다. 대표적인 문제는 다음과 같습니다. 첫째, N+1 문제입니다. 목록을 조회한 뒤 각 엔티티의 연관을 지연 로딩으로 꺼내면 행 수만큼 추가 쿼리가 나갑니다. 페치 조인이나 배치 사이즈로 대응합니다. 둘째, 의도치 않은 쿼리입니다. 값만 바꿔도 변경 감지로 UPDATE가 나가고, 컬렉션을 건드리면 예상 못 한 삭제와 삽입이 발생하기도 합니다. 셋째, 대량 처리 부적합입니다. 수만 건을 하나씩 엔티티로 다루면 영속성 컨텍스트가 비대해져 메모리와 비교 비용이 폭증하므로, 이런 작업은 벌크 연산이나 직접 작성한 SQL이 낫습니다. 넷째, 복잡한 통계 쿼리를 억지로 객체 질의로 표현하려다 오히려 읽기 어려워지는 경우입니다. 자세로 정리하면, ORM은 반복적인 매핑과 단순 CRUD를 줄여 주는 도구로 쓰고 실제로 어떤 SQL이 나가는지 항상 확인해야 합니다. 개발 중에는 쿼리 로그를 켜 두고, 성능이 중요한 조회는 처음부터 원하는 SQL을 정한 뒤 그것이 나오도록 작성하는 편이 안전합니다.');
SET @e48 = LAST_INSERT_ID();

-- e49 [주 태그: N+1 문제] — 발생과 해결
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('N+1 문제의 원인과 해결', 'ORM에서 N+1 문제가 왜 발생하는지 설명하고 해결 방법을 비교하시오.', 'ESSAY', 'MEDIUM', 'DB',
 'N+1 문제는 목록을 한 번의 쿼리로 조회한 뒤, 각 엔티티의 연관 데이터를 꺼낼 때마다 추가 쿼리가 나가 총 N+1번이 실행되는 현상입니다. 게시글 100건을 조회하고 각 게시글의 작성자 이름을 출력하면 게시글 조회 1번에 작성자 조회 100번이 더해집니다. 원인은 ORM이 연관 데이터를 필요해지는 시점에 개별적으로 가져오기 때문입니다. 해결 방법은 몇 가지입니다. 첫째, 페치 조인으로 필요한 연관을 처음부터 한 번에 가져옵니다. 가장 직접적이지만 일대다를 여러 개 조인하면 행이 곱으로 불어나 페이징이 어긋나는 문제가 있습니다. 둘째, 배치 사이즈를 설정해 연관 조회를 IN 절로 묶습니다. 쿼리 수가 N에서 몇 개로 줄고 페이징과도 잘 맞아 일대다에서는 이쪽이 안전합니다. 셋째, 엔티티 대신 필요한 값만 담는 DTO로 직접 조회합니다. 조회 전용 화면에서는 이 방법이 가장 단순합니다. 즉시 로딩으로 바꾸는 것은 해결책이 아닙니다. 조회 시점만 앞당길 뿐 쿼리 수는 그대로이며 필요 없는 연관까지 항상 읽게 되어 오히려 나빠집니다.');
SET @e49 = LAST_INSERT_ID();

-- e50 [주 태그: N+1 문제] — 발견과 예방
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('N+1 문제를 미리 발견하기', 'N+1 문제가 운영 환경에서 드러나기 전에 개발 단계에서 발견하려면 어떻게 해야 하는지 논하시오.', 'ESSAY', 'HIGH', 'DB',
 'N+1은 데이터가 적은 개발 환경에서는 티가 나지 않다가 운영에서 터지는 것이 특징입니다. 목록이 10건일 때는 쿼리 11번이 순식간에 끝나지만 1000건이 되면 1001번이 되기 때문입니다. 그래서 응답 시간이 아니라 쿼리 개수를 봐야 합니다. 방법은 다음과 같습니다. 첫째, 개발 환경에서 SQL 로그를 항상 켜 두고 화면 하나를 열 때 몇 개의 쿼리가 나가는지 눈으로 확인합니다. 같은 형태의 쿼리가 반복되면 신호입니다. 둘째, 요청 단위로 실행된 쿼리 수를 세어 임계치를 넘으면 경고하거나 테스트를 실패시키는 장치를 둡니다. 셋째, 통합 테스트에서 실제로 실행된 쿼리 수를 검증합니다. 목록 조회 테스트에 데이터를 여러 건 넣어 두고 쿼리가 상수 개만 나가는지 단언하면, 나중에 누군가 연관 필드를 참조하는 코드를 추가했을 때 곧바로 잡힙니다. 넷째, 개발용 데이터에 최소한의 볼륨을 채워 둡니다. 한두 건만 있는 데이터베이스로는 이 문제를 영원히 못 봅니다. 예방 측면에서는 연관 관계의 기본 페치 전략을 지연 로딩으로 두고, 필요한 화면마다 어떤 연관을 함께 가져올지 명시적으로 정하는 습관이 도움이 됩니다.');
SET @e50 = LAST_INSERT_ID();


