INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('대칭키와 비대칭키의 핵심 개념', '대칭키와 비대칭키에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'NETWORK',
 '대칭키는 같은 키로 암복호화하고, 비대칭키는 공개키와 개인키 쌍을 이용해 키 교환과 신원 검증에 활용한다.');
SET @nwq2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('3-way handshake의 핵심 개념', '3-way handshake에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'NETWORK',
 'TCP가 SYN, SYN-ACK, ACK를 교환해 양쪽의 송수신 준비 상태와 초기 순서 번호를 확인하는 연결 수립 절차다.');
SET @nwq2_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('쿠키와 세션의 핵심 개념', '쿠키와 세션에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'NETWORK',
 '쿠키는 클라이언트에 저장되고 세션은 서버에 상태를 보관하며, 보통 쿠키에는 세션 식별자만 담는다.');
SET @nwq2_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('흐름 제어의 핵심 개념', '흐름 제어에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'NETWORK',
 '수신 버퍼가 넘치지 않도록 수신자가 처리 가능한 양에 맞춰 송신량을 조절하는 TCP 기능이다.');
SET @nwq2_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('토큰 인증의 핵심 개념', '토큰 인증에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'NETWORK',
 '서버가 발급한 토큰을 요청마다 제시해 사용자를 검증하는 방식으로, 서명 검증과 만료·탈취 대응이 중요하다.');
SET @nwq2_4 = LAST_INSERT_ID();
