('혼잡 제어의 핵심 개념', '혼잡 제어에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'NETWORK',
 '네트워크 경로의 과부하를 피하도록 손실과 지연 신호에 따라 송신 윈도우와 전송 속도를 조절하는 기능이다.');
