INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('웹소켓의 핵심 개념', '웹소켓에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'NETWORK',
 'HTTP 핸드셰이크 뒤 하나의 연결에서 서버와 클라이언트가 양방향으로 실시간 메시지를 주고받게 하는 프로토콜이다.');
