INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('프록시와 리버스 프록시의 핵심 개념', '프록시와 리버스 프록시에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'NETWORK',
 '프록시는 클라이언트 대신 외부에 요청하고, 리버스 프록시는 서버 앞에서 요청을 받아 내부 서버로 전달한다.');
SET @nwq4_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('DNS의 핵심 개념', 'DNS에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'NETWORK',
