INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@nwq4_2, 'DNS은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @nwq4),
(@nwq4_2, '사람이 읽는 도메인 이름을 통신 가능한 IP 주소 등 DNS 레코드로 해석하는 분산 시스템이다.', 2, TRUE, '', @nwq4),
