INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('CDN의 핵심 개념', 'CDN에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'NETWORK',
 '사용자와 가까운 엣지 서버에 정적 또는 캐시 가능한 콘텐츠를 배치해 전송 지연과 원본 서버 부하를 낮추는 네트워크다.');
SET @nwq5 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('HTTP 상태 코드의 핵심 개념', 'HTTP 상태 코드에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'NETWORK',
 '요청 처리 결과를 1xx부터 5xx까지의 표준 숫자로 표현해 클라이언트가 다음 행동을 판단하게 하는 규약이다.');
SET @nwq5_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('URL 요청 처리 흐름의 핵심 개념', 'URL 요청 처리 흐름에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'NETWORK',
 '브라우저가 DNS 해석과 연결 수립을 거쳐 HTTP 요청을 보내고 서버 응답을 받아 렌더링하는 전체 과정이다.');
SET @nwq5_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('HTTP 버전의 핵심 개념', 'HTTP 버전에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'NETWORK',
 'HTTP/1.1·HTTP/2·HTTP/3은 연결과 다중화 방식이 달라 성능 특성과 헤드 오브 라인 블로킹 대응이 다르다.');
SET @nwq5_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('IPv4와 IPv6의 핵심 개념', 'IPv4와 IPv6에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'NETWORK',
 'IPv4는 32비트 주소 체계이고 IPv6는 주소 고갈을 해결하기 위해 128비트 주소와 개선된 헤더 구조를 사용한다.');
SET @nwq5_4 = LAST_INSERT_ID();
