('누적 합의 핵심 개념', '누적 합에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'ALGORITHM',
 '배열의 앞에서부터 합을 미리 저장해 구간 합을 상수 시간에 계산하도록 하는 전처리 기법이다.');
SET @alq1_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('공간 복잡도의 핵심 개념', '공간 복잡도에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'ALGORITHM',
 '알고리즘이 입력 외에 실행 중 추가로 사용하는 메모리 양의 증가율을 나타내는 척도다.');
SET @alq1_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('DFS의 핵심 개념', 'DFS에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'ALGORITHM',
 '한 경로를 가능한 깊게 탐색한 뒤 되돌아와 다음 경로를 탐색하는 그래프·트리 탐색 방식이다.');
SET @alq1_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('BFS의 핵심 개념', 'BFS에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'ALGORITHM',
 '시작점에서 가까운 정점을 먼저 방문하도록 큐를 이용해 너비 단위로 탐색하는 방식이다.');
SET @alq1_4 = LAST_INSERT_ID();
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@alq1, '입력 크기가 증가할 때 알고리즘 실행 횟수가 어떻게 증가하는지를 점근적으로 나타내는 척도다.', 1, TRUE, '', @alq1_1),
(@alq1, '시간 복잡도은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @alq1_2),
(@alq1, '시간 복잡도은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @alq1_3),
(@alq1, '시간 복잡도은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @alq1_4);
