('최단 경로의 핵심 개념', '최단 경로에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'ALGORITHM',
 '그래프에서 두 정점 사이의 가중치 합 또는 간선 수가 최소인 경로를 찾는 문제와 알고리즘을 말한다.');
SET @alq2_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('완전 탐색의 핵심 개념', '완전 탐색에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'ALGORITHM',
 '가능한 모든 후보를 빠짐없이 확인해 정답을 찾는 방식으로, 입력 범위와 가지치기가 핵심이다.');
SET @alq2_2 = LAST_INSERT_ID();
