(@alq4, '매 단계에서 현재 가장 좋아 보이는 선택을 하며, 그 선택이 전역 최적해를 보장하는지 증명해야 하는 기법이다.', 4, TRUE, '', @alq4_4);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@alq4_1, '정렬된 탐색 공간에서 중앙값과 비교해 절반씩 범위를 줄여 대상을 찾는 알고리즘이다.', 1, TRUE, '', @alq4),
