INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@alq5_4, '조합은 순서를 고려하지 않고 선택하며, 순열은 순서를 고려해 배열하는 경우의 수 개념이다.', 1, TRUE, '', @alq5),
(@alq5_4, '조합과 순열은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @alq5),
(@alq5_4, '조합과 순열은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @alq5),
(@alq5_4, '조합과 순열은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @alq5);

-- ALGORITHM 서술형 문항
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('시간 복잡도의 원리와 목적', '시간 복잡도의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'LOW', 'ALGORITHM',
