 '연결 그래프의 모든 정점을 사이클 없이 연결하면서 간선 가중치 합을 최소로 만드는 트리다. 따라서 적용 전에는 요구 사항, 데이터 또는 트래픽 규모, 실패 시 영향, 운영 복잡도를 확인해야 한다. 이 개념을 만능 해법으로 쓰지 말고 측정과 검증을 통해 적합성을 판단한다.');
SET @ale9_2 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@ale9_2, (SELECT id FROM tag WHERE name = '최소 신장 트리')),
(@ale9_2, (SELECT id FROM tag WHERE name = '그리디'));
