INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('배열의 핵심 개념', '배열에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DATA_STRUCTURE',
 '연속된 메모리에 같은 타입 원소를 저장해 인덱스 접근은 빠르지만 중간 삽입과 삭제 비용이 큰 구조다.');
SET @dsq1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('이진 탐색 트리의 핵심 개념', '이진 탐색 트리에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DATA_STRUCTURE',
 '왼쪽 서브트리의 키는 작고 오른쪽은 큰 순서 규칙을 가져 탐색·삽입·삭제를 수행하는 트리다.');
SET @dsq1_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('동적 배열의 핵심 개념', '동적 배열에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DATA_STRUCTURE',
 '연속 메모리 배열의 용량이 부족할 때 더 큰 공간을 확보해 원소를 복사함으로써 크기를 늘리는 구조다.');
SET @dsq1_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('균형 이진 트리의 핵심 개념', '균형 이진 트리에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DATA_STRUCTURE',
 '트리 높이가 한쪽으로 치우치지 않도록 회전 등의 규칙을 적용해 연산을 O(log n)으로 유지하는 트리다.');
SET @dsq1_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('연결 리스트의 핵심 개념', '연결 리스트에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DATA_STRUCTURE',
 '각 노드가 다음 노드의 참조를 가져 비연속 메모리에서도 연결되며, 위치를 알면 삽입·삭제가 빠른 구조다.');
SET @dsq1_4 = LAST_INSERT_ID();
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@dsq1, '연속된 메모리에 같은 타입 원소를 저장해 인덱스 접근은 빠르지만 중간 삽입과 삭제 비용이 큰 구조다.', 1, TRUE, '', @dsq1_1),
(@dsq1, '배열은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq1_2),
(@dsq1, '배열은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq1_3),
(@dsq1, '배열은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq1_4);
