INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('레드-블랙 트리의 핵심 개념', '레드-블랙 트리에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DATA_STRUCTURE',
 '색 규칙으로 높이를 제한해 탐색·삽입·삭제의 최악 시간을 O(log n)으로 보장하는 자가 균형 BST다.');
SET @dsq2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('이중 연결 리스트의 핵심 개념', '이중 연결 리스트에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DATA_STRUCTURE',
 '각 노드가 이전과 다음 노드 참조를 모두 가져 양방향 이동과 노드 삭제를 쉽게 하는 연결 리스트다.');
SET @dsq2_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('스택의 핵심 개념', '스택에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DATA_STRUCTURE',
 '마지막에 넣은 원소를 먼저 꺼내는 LIFO 규칙을 따르며 함수 호출과 되돌리기에 쓰이는 구조다.');
SET @dsq2_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('B+트리의 핵심 개념', 'B+트리에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DATA_STRUCTURE',
 '내부 노드는 탐색 키만, 리프 노드는 실제 데이터와 연결 포인터를 가져 범위 조회에 유리한 다진 균형 트리다.');
SET @dsq2_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('큐의 핵심 개념', '큐에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DATA_STRUCTURE',
 '먼저 넣은 원소를 먼저 꺼내는 FIFO 규칙을 따르며 작업 대기열과 BFS에 쓰이는 구조다.');
SET @dsq2_4 = LAST_INSERT_ID();
