SET @dsq4_4 = LAST_INSERT_ID();
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@dsq4, '해시 테이블은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq4_1),
(@dsq4, '해시 테이블은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq4_2),
(@dsq4, '해시 테이블은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq4_3),
(@dsq4, '키를 해시 값으로 배열 위치에 매핑해 평균 O(1) 탐색·삽입·삭제를 제공하는 구조다.', 4, TRUE, '', @dsq4_4);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
