INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('트리의 핵심 개념', '트리에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DATA_STRUCTURE',
 '노드 사이에 부모·자식 계층 관계가 있고 사이클이 없는 비선형 자료구조다.');
