('트리 순회의 핵심 개념', '트리 순회에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DATA_STRUCTURE',
 '트리의 모든 노드를 전위·중위·후위 또는 레벨 순서로 한 번씩 방문하는 방법이다.');
SET @dsq5_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('완전 이진 트리의 핵심 개념', '완전 이진 트리에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DATA_STRUCTURE',
 '마지막 레벨을 제외한 모든 레벨이 채워지고 마지막 레벨은 왼쪽부터 채워지는 이진 트리다.');
