(@dsq5_3, '마지막 레벨을 제외한 모든 레벨이 채워지고 마지막 레벨은 왼쪽부터 채워지는 이진 트리다.', 4, TRUE, '', @dsq5);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@dsq5_4, '재귀 호출이 종료되지 않거나 호출 깊이가 스택 한도를 넘을 때 호출 스택이 고갈되는 문제다.', 1, TRUE, '', @dsq5),
(@dsq5_4, '스택 오버플로와 재귀 깊이은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq5),
(@dsq5_4, '스택 오버플로와 재귀 깊이은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dsq5),
