INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('프로세스의 핵심 개념', '프로세스에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'OS',
 '실행 중인 프로그램의 독립된 자원 단위로 주소 공간과 PCB 등 운영체제 관리 정보를 가진다.');
SET @osq1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('사용자 모드와 커널 모드의 핵심 개념', '사용자 모드와 커널 모드에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'OS',
 '사용자 모드는 제한된 권한으로 실행되고 커널 모드는 하드웨어와 핵심 자원에 접근할 수 있는 보호 체계다.');
SET @osq1_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('스레드의 핵심 개념', '스레드에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'OS',
 '프로세스 안에서 실행 흐름을 나타내며 코드·데이터 등 프로세스 자원을 공유하면서 독립된 스택과 레지스터를 가진다.');
SET @osq1_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('시스템 콜의 핵심 개념', '시스템 콜에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'OS',
 '사용자 프로그램이 파일·프로세스·네트워크 같은 커널 기능을 안전하게 요청하기 위한 모드 전환 인터페이스다.');
SET @osq1_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('PCB의 핵심 개념', 'PCB에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'OS',
 '프로세스 상태, 레지스터, 스케줄링 정보, 메모리 정보를 보관해 중단된 프로세스를 다시 실행하게 하는 자료구조다.');
SET @osq1_4 = LAST_INSERT_ID();
