INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@osq2_1, '멀티프로세스와 멀티스레드은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_1, '멀티프로세스와 멀티스레드은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_1, '프로세스는 주소 공간을 분리해 격리가 강하고, 스레드는 메모리를 공유해 가볍지만 동기화가 필요하다.', 3, TRUE, '', @osq2),
(@osq2_1, '멀티프로세스와 멀티스레드은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@osq2_2, '컨텍스트 스위칭은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_2, '컨텍스트 스위칭은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_2, '컨텍스트 스위칭은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_2, 'CPU가 실행 중인 작업의 상태를 저장하고 다른 작업의 상태를 복원해 실행 대상을 바꾸는 과정이다.', 4, TRUE, '', @osq2);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@osq2_3, '프로세스에 큰 연속 주소 공간이 있는 것처럼 보이게 하고 필요한 부분만 물리 메모리에 올리는 메모리 관리 기법이다.', 1, TRUE, '', @osq2),
(@osq2_3, '가상 메모리은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_3, '가상 메모리은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_3, '가상 메모리은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@osq2_4, 'IPC은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_4, '서로 분리된 프로세스가 데이터와 신호를 교환하도록 파이프·소켓·공유 메모리 등을 제공하는 통신 방식이다.', 2, TRUE, '', @osq2),
(@osq2_4, 'IPC은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2),
(@osq2_4, 'IPC은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @osq2);

