INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('페이징의 핵심 개념', '페이징에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'OS',
 '가상 주소와 물리 메모리를 같은 크기의 페이지와 프레임으로 나누어 페이지 테이블로 매핑하는 기법이다.');
SET @osq3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('CPU 스케줄링의 핵심 개념', 'CPU 스케줄링에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'OS',
 '준비 상태 작업 중 다음에 CPU를 사용할 작업을 선택해 응답 시간·처리량·공정성을 조절하는 정책이다.');
SET @osq3_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('세그멘테이션의 핵심 개념', '세그멘테이션에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'OS',
 '코드·데이터·스택처럼 의미 단위의 가변 길이 세그먼트로 메모리를 나누어 주소를 관리하는 방식이다.');
SET @osq3_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('임계 구역의 핵심 개념', '임계 구역에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'OS',
 '공유 자원에 접근하는 코드 구간으로 동시에 실행되면 경쟁 상태가 생기므로 상호 배제가 필요하다.');
