INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('페이지 교체 알고리즘의 핵심 개념', '페이지 교체 알고리즘에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'OS',
 '페이지 폴트 때 빈 프레임이 없으면 어떤 페이지를 내보낼지 결정해 폴트 횟수와 성능에 영향을 주는 정책이다.');
SET @osq3_4 = LAST_INSERT_ID();
