INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('뮤텍스와 세마포어의 핵심 개념', '뮤텍스와 세마포어에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'OS',
 '뮤텍스는 하나의 소유자가 잠그는 상호 배제 도구이고 세마포어는 허가 수를 세어 여러 자원을 제어할 수 있다.');
SET @osq4 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('스와핑의 핵심 개념', '스와핑에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'OS',
 '메모리 부족 시 프로세스 또는 메모리 내용을 보조 기억장치로 내보내고 필요할 때 다시 가져오는 기법이다.');
