INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('경쟁 상태의 핵심 개념', '경쟁 상태에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'OS',
 '여러 실행 흐름의 수행 순서에 따라 공유 데이터 결과가 달라지는 동시성 오류다.');
