('파일 시스템의 핵심 개념', '파일 시스템에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'OS',
 '저장 장치 위에서 파일과 디렉터리를 이름·권한·블록 단위로 관리하고 접근하는 운영체제 구조다.');
