('동기와 비동기의 핵심 개념', '동기와 비동기에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'OS',
 '동기 호출은 완료를 기다려 결과를 받으며 비동기 호출은 완료를 기다리지 않고 나중에 결과를 처리하는 방식이다.');
