INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('프로세스의 원리와 목적', '프로세스의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'LOW', 'OS',
 '실행 중인 프로그램의 독립된 자원 단위로 주소 공간과 PCB 등 운영체제 관리 정보를 가진다. 면접 답변에서는 이 정의만 나열하지 말고, 어떤 문제를 해결하려는지와 다른 선택지 대비 장단점을 함께 설명해야 한다.');
