('블로킹과 논블로킹의 적용 판단', '실무에서 블로킹과 논블로킹을 적용할 때 확인해야 할 조건과 주의점을 설명하시오.', 'ESSAY', 'LOW', 'OS',
 '블로킹 호출은 작업이 끝날 때까지 제어를 반환하지 않고, 논블로킹 호출은 즉시 반환해 호출자가 다른 일을 할 수 있게 한다. 따라서 적용 전에는 요구 사항, 데이터 또는 트래픽 규모, 실패 시 영향, 운영 복잡도를 확인해야 한다. 이 개념을 만능 해법으로 쓰지 말고 측정과 검증을 통해 적합성을 판단한다.');
SET @ose24_2 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@ose24_2, (SELECT id FROM tag WHERE name = '블로킹과 논블로킹')),
(@ose24_2, (SELECT id FROM tag WHERE name = '동기와 비동기')),
(@ose24_2, (SELECT id FROM tag WHERE name = '스레드 풀'));
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('스레드 풀의 원리와 목적', '스레드 풀의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'LOW', 'OS',
 '재사용할 워커 스레드를 미리 만들고 작업 큐에서 일을 배정해 생성 비용과 동시 실행 수를 관리하는 방식이다. 면접 답변에서는 이 정의만 나열하지 말고, 어떤 문제를 해결하려는지와 다른 선택지 대비 장단점을 함께 설명해야 한다.');
SET @ose25_1 = LAST_INSERT_ID();
