INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@dpq1, '변경에 유연하고 이해하기 쉬운 객체 설계를 위한 단일 책임·개방 폐쇄·리스코프 치환·인터페이스 분리·의존성 역전 원칙이다.', 1, TRUE, '', @dpq1_1),
(@dpq1, 'SOLID은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq1_2),
