(@dpq1_4, '상속과 합성은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq1),
(@dpq1_4, '상속과 합성은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq1),
(@dpq1_4, '상속과 합성은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq1);

-- DESIGN_PATTERN 객관식 그룹 2
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('프록시의 핵심 개념', '프록시에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DESIGN_PATTERN',
 '대상 객체와 같은 인터페이스를 가진 대리 객체가 접근 제어·지연 로딩·로깅 같은 부가 작업을 대신 처리하는 패턴이다.');
SET @dpq2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('의존성 주입과 IoC의 핵심 개념', '의존성 주입과 IoC에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DESIGN_PATTERN',
 '객체가 의존성을 직접 만들지 않고 외부 컨테이너가 제공해 결합도를 낮추고 생성 제어를 역전하는 방식이다.');
SET @dpq2_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('전략의 핵심 개념', '전략에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DESIGN_PATTERN',
 '교체 가능한 알고리즘을 공통 인터페이스로 캡슐화하고 실행 시 필요한 구현을 선택하게 하는 패턴이다.');
