INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('DTO와 VO의 핵심 개념', 'DTO와 VO에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DESIGN_PATTERN',
 'DTO는 계층 또는 네트워크 사이 데이터를 전달하는 객체이고, VO는 값 자체의 동등성과 불변성이 중요한 값 객체다.');
SET @dpq5 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('불변성과 부작용의 핵심 개념', '불변성과 부작용에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DESIGN_PATTERN',
 '불변성은 생성 뒤 상태가 바뀌지 않는 성질이며, 부작용은 함수가 외부 상태를 바꾸는 것으로 둘을 줄이면 추론이 쉬워진다.');
SET @dpq5_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('SOLID의 핵심 개념', 'SOLID에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'DESIGN_PATTERN',
 '변경에 유연하고 이해하기 쉬운 객체 설계를 위한 단일 책임·개방 폐쇄·리스코프 치환·인터페이스 분리·의존성 역전 원칙이다.');
SET @dpq5_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('데코레이터의 핵심 개념', '데코레이터에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'DESIGN_PATTERN',
 '객체를 감싸 같은 인터페이스를 유지한 채 책임과 기능을 런타임에 조합하여 추가하는 패턴이다.');
SET @dpq5_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('결합도와 응집도의 핵심 개념', '결합도와 응집도에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'DESIGN_PATTERN',
 '모듈 간 의존성은 낮추고 하나의 모듈 안의 책임 관련성은 높여 변경 영향을 줄이는 설계 기준이다.');
SET @dpq5_4 = LAST_INSERT_ID();
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@dpq5, 'DTO는 계층 또는 네트워크 사이 데이터를 전달하는 객체이고, VO는 값 자체의 동등성과 불변성이 중요한 값 객체다.', 1, TRUE, '', @dpq5_1),
(@dpq5, 'DTO와 VO은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq5_2),
(@dpq5, 'DTO와 VO은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq5_3),
(@dpq5, 'DTO와 VO은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @dpq5_4);
