-- DESIGN_PATTERN 서술형 문항
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('SOLID의 원리와 목적', 'SOLID의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'LOW', 'DESIGN_PATTERN',
 '변경에 유연하고 이해하기 쉬운 객체 설계를 위한 단일 책임·개방 폐쇄·리스코프 치환·인터페이스 분리·의존성 역전 원칙이다. 면접 답변에서는 이 정의만 나열하지 말고, 어떤 문제를 해결하려는지와 다른 선택지 대비 장단점을 함께 설명해야 한다.');
SET @dpe1_1 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@dpe1_1, (SELECT id FROM tag WHERE name = 'SOLID')),
(@dpe1_1, (SELECT id FROM tag WHERE name = '결합도와 응집도')),
(@dpe1_1, (SELECT id FROM tag WHERE name = '의존성 주입과 IoC'));
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('SOLID의 적용 판단', '실무에서 SOLID을 적용할 때 확인해야 할 조건과 주의점을 설명하시오.', 'ESSAY', 'MEDIUM', 'DESIGN_PATTERN',
 '변경에 유연하고 이해하기 쉬운 객체 설계를 위한 단일 책임·개방 폐쇄·리스코프 치환·인터페이스 분리·의존성 역전 원칙이다. 따라서 적용 전에는 요구 사항, 데이터 또는 트래픽 규모, 실패 시 영향, 운영 복잡도를 확인해야 한다. 이 개념을 만능 해법으로 쓰지 말고 측정과 검증을 통해 적합성을 판단한다.');
SET @dpe1_2 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@dpe1_2, (SELECT id FROM tag WHERE name = 'SOLID')),
(@dpe1_2, (SELECT id FROM tag WHERE name = '결합도와 응집도')),
(@dpe1_2, (SELECT id FROM tag WHERE name = '의존성 주입과 IoC'));
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('SOLID의 트레이드오프', 'SOLID을 선택했을 때 얻는 이점과 감수해야 할 트레이드오프를 설명하시오.', 'ESSAY', 'HIGH', 'DESIGN_PATTERN',
 '변경에 유연하고 이해하기 쉬운 객체 설계를 위한 단일 책임·개방 폐쇄·리스코프 치환·인터페이스 분리·의존성 역전 원칙이다. 이점은 해당 문제를 명확히 분리하거나 효율적으로 다룰 수 있다는 점이고, 반대로 설계·운영·학습 비용이 생길 수 있다. 팀의 요구와 제약을 기준으로 선택해야 한다.');
SET @dpe1_3 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@dpe1_3, (SELECT id FROM tag WHERE name = 'SOLID')),
(@dpe1_3, (SELECT id FROM tag WHERE name = '결합도와 응집도')),
(@dpe1_3, (SELECT id FROM tag WHERE name = '의존성 주입과 IoC'));
