INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('GoF의 적용 판단', '실무에서 GoF을 적용할 때 확인해야 할 조건과 주의점을 설명하시오.', 'ESSAY', 'MEDIUM', 'DESIGN_PATTERN',
 '생성·구조·행위 세 범주로 분류한 재사용 가능한 객체지향 디자인 패턴 모음이다. 따라서 적용 전에는 요구 사항, 데이터 또는 트래픽 규모, 실패 시 영향, 운영 복잡도를 확인해야 한다. 이 개념을 만능 해법으로 쓰지 말고 측정과 검증을 통해 적합성을 판단한다.');
SET @dpe19_2 = LAST_INSERT_ID();
