('동시성 제어의 핵심 개념', '동시성 제어에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'LANGUAGE',
 '여러 스레드가 공유 자원에 접근할 때 원자성·가시성·순서를 보장해 경쟁 상태를 막는 기법이다.');
SET @lgq3_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('어노테이션의 핵심 개념', '어노테이션에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'LANGUAGE',
 '코드에 메타데이터를 붙여 컴파일러·프레임워크·리플렉션이 선언적 설정과 검증에 활용하게 하는 기능이다.');
