INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('JVM 구조의 핵심 개념', 'JVM 구조에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'LANGUAGE',
 '자바 바이트코드를 실행하며 클래스 로더, 런타임 메모리 영역, 실행 엔진, 가비지 컬렉터로 구성되는 가상 머신 구조다.');
SET @lgq3_4 = LAST_INSERT_ID();
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@lgq3, '직렬화은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @lgq3_1),
(@lgq3, '직렬화은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @lgq3_2),
(@lgq3, '객체 상태를 바이트 스트림으로 변환해 저장 또는 전송하고 다시 객체로 복원하는 과정이다.', 3, TRUE, '', @lgq3_3),
(@lgq3, '직렬화은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @lgq3_4);
