INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('원시 타입과 래퍼의 핵심 개념', '원시 타입과 래퍼에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'LANGUAGE',
 '원시 타입은 값을 직접 보관하고 래퍼 클래스는 객체가 필요한 컬렉션·제네릭 환경에서 원시 값을 객체로 감싼다.');
SET @lgq4 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('클래스 로더의 핵심 개념', '클래스 로더에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'LANGUAGE',
 '클래스 파일을 메모리에 로드하고 링크·초기화하며 부모 우선 위임으로 핵심 클래스의 일관성과 보안을 지키는 구성요소다.');
SET @lgq4_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('오토박싱의 핵심 개념', '오토박싱에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'LANGUAGE',
 '원시 타입과 래퍼 객체 사이의 변환을 컴파일러가 자동으로 처리하는 기능으로 null 언박싱과 성능 비용에 주의해야 한다.');
