INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('JIT 컴파일러의 핵심 개념', 'JIT 컴파일러에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'LANGUAGE',
 '실행 중 자주 수행되는 바이트코드를 네이티브 코드로 컴파일해 JVM 프로그램의 반복 실행 성능을 높이는 엔진이다.');
SET @lgq4_3 = LAST_INSERT_ID();
