(@lgq4_2, '오토박싱은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @lgq4);
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@lgq4_3, 'JIT 컴파일러은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 1, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @lgq4),
