(@lgq4_3, '실행 중 자주 수행되는 바이트코드를 네이티브 코드로 컴파일해 JVM 프로그램의 반복 실행 성능을 높이는 엔진이다.', 3, TRUE, '', @lgq4),
(@lgq4_3, 'JIT 컴파일러은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @lgq4);
