INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('객체지향 4대 특성의 원리와 목적', '객체지향 4대 특성의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'LOW', 'LANGUAGE',
 '캡슐화·상속·다형성·추상화로 상태와 행위를 모델링하고 변경 가능한 부분을 분리하는 객체지향 핵심 특성이다. 면접 답변에서는 이 정의만 나열하지 말고, 어떤 문제를 해결하려는지와 다른 선택지 대비 장단점을 함께 설명해야 한다.');
SET @lge1_1 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@lge1_1, (SELECT id FROM tag WHERE name = '객체지향 4대 특성')),
(@lge1_1, (SELECT id FROM tag WHERE name = '인터페이스와 추상 클래스')),
(@lge1_1, (SELECT id FROM tag WHERE name = '오버로딩과 오버라이딩'));
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
