-- GENERAL_CS 객관식 그룹 1
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('OAuth 2.0의 핵심 개념', 'OAuth 2.0에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'GENERAL_CS',
 '사용자 비밀번호를 제3자 앱에 주지 않고 권한 부여 서버가 발급한 액세스 토큰으로 보호 자원 접근을 위임하는 프로토콜이다.');
SET @gcq1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('OIDC의 핵심 개념', 'OIDC에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'GENERAL_CS',
 'OAuth 2.0 위에 인증 계층을 더해 ID 토큰과 사용자 정보로 사용자의 신원을 확인하게 하는 표준이다.');
SET @gcq1_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('JWT의 핵심 개념', 'JWT에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'GENERAL_CS',
 '헤더·페이로드·서명으로 구성되어 위변조 검증이 가능한 토큰 형식이며, 만료·탈취·폐기 전략을 함께 설계해야 한다.');
SET @gcq1_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('인증과 인가의 핵심 개념', '인증과 인가에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'GENERAL_CS',
 '인증은 사용자가 누구인지 확인하는 절차이고, 인가는 확인된 사용자가 특정 자원이나 작업을 해도 되는지 결정하는 절차다.');
SET @gcq1_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('비밀번호 저장과 해싱의 핵심 개념', '비밀번호 저장과 해싱에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'GENERAL_CS',
 '비밀번호는 복호화 가능한 암호문이 아니라 salt와 느린 단방향 해시로 저장해 유출 피해를 줄여야 한다.');
SET @gcq1_4 = LAST_INSERT_ID();
INSERT INTO answer_choice (question_id, content, sequence, is_correct, explanation, related_question_id) VALUES
(@gcq1, '사용자 비밀번호를 제3자 앱에 주지 않고 권한 부여 서버가 발급한 액세스 토큰으로 보호 자원 접근을 위임하는 프로토콜이다.', 1, TRUE, '', @gcq1_1),
(@gcq1, 'OAuth 2.0은 적용 조건이나 한계를 확인할 필요 없이 모든 상황에서 같은 방식으로 사용하면 되는 개념이다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @gcq1_2),
(@gcq1, 'OAuth 2.0은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 3, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @gcq1_3),
(@gcq1, 'OAuth 2.0은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @gcq1_4);
