INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('SQL 인젝션의 핵심 개념', 'SQL 인젝션에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'GENERAL_CS',
 '외부 입력이 SQL 문법으로 해석되어 의도하지 않은 쿼리가 실행되는 취약점으로, 바인딩 파라미터로 막는다.');
