INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('XSS와 CSRF의 핵심 개념', 'XSS와 CSRF에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'GENERAL_CS',
 'XSS는 악성 스크립트를 페이지에 주입하는 공격이고 CSRF는 로그인된 사용자의 브라우저로 원치 않는 요청을 보내는 공격이다.');
SET @gcq2_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('접근 제어와 권한 모델의 핵심 개념', '접근 제어와 권한 모델에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'GENERAL_CS',
 '사용자·역할·권한과 자원·행동의 관계를 정책으로 정의하고 서버에서 일관되게 집행하는 보안 설계다.');
