(@gcq2_1, 'XSS는 악성 스크립트를 페이지에 주입하는 공격이고 CSRF는 로그인된 사용자의 브라우저로 원치 않는 요청을 보내는 공격이다.', 3, TRUE, '', @gcq2),
(@gcq2_1, 'XSS와 CSRF은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @gcq2);
