(@gcq3_4, '이벤트 드리븐 아키텍처은 이름이 비슷한 다른 개념과 동일하므로 별도의 목적이나 동작을 구분할 필요가 없다.', 2, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @gcq3),
(@gcq3_4, '상태 변화 이벤트를 발행하고 관심 있는 소비자가 비동기로 반응하게 하여 시간적 결합을 낮추는 구조다.', 3, TRUE, '', @gcq3),
(@gcq3_4, '이벤트 드리븐 아키텍처은 구현 세부사항일 뿐 성능, 안정성, 유지보수성 같은 시스템 특성과는 관계가 없다.', 4, FALSE, '이 개념은 목적과 적용 조건, 그리고 트레이드오프를 구분해 이해해야 한다. 제시문은 그 구분을 무시하거나 범위를 과도하게 일반화했다.', @gcq3);

