INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('분산 트랜잭션과 사가의 핵심 개념', '분산 트랜잭션과 사가에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'GENERAL_CS',
 '여러 서비스의 일관성을 전역 락 대신 로컬 트랜잭션과 보상 작업의 연속으로 맞추는 패턴이다.');
SET @gcq4 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('멱등성의 핵심 개념', '멱등성에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'GENERAL_CS',
 '같은 요청을 여러 번 수행해도 시스템 상태와 결과가 한 번 수행한 것과 같게 만드는 성질이다.');
SET @gcq4_1 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('캐시 전략의 핵심 개념', '캐시 전략에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'HIGH', 'GENERAL_CS',
 '재사용 가능한 데이터를 가까운 저장소에 두고 TTL·무효화·갱신 정책으로 성능과 최신성의 균형을 맞추는 방법이다.');
SET @gcq4_2 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('분산 캐시의 핵심 개념', '분산 캐시에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'LOW', 'GENERAL_CS',
 '여러 애플리케이션 인스턴스가 공유하는 외부 캐시에 데이터를 저장해 확장 환경에서도 일관된 빠른 조회를 제공하는 방식이다.');
SET @gcq4_3 = LAST_INSERT_ID();
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('확장성과 스케일 아웃의 핵심 개념', '확장성과 스케일 아웃에 대한 설명으로 가장 적절한 것은?', 'MULTIPLE_CHOICE', 'MEDIUM', 'GENERAL_CS',
 '부하 증가에 맞춰 시스템 용량을 늘리는 능력이며 스케일 아웃은 서버 인스턴스를 수평으로 추가하는 방식이다.');
SET @gcq4_4 = LAST_INSERT_ID();
