INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('OAuth 2.0의 원리와 목적', 'OAuth 2.0의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'LOW', 'GENERAL_CS',
 '사용자 비밀번호를 제3자 앱에 주지 않고 권한 부여 서버가 발급한 액세스 토큰으로 보호 자원 접근을 위임하는 프로토콜이다. 면접 답변에서는 이 정의만 나열하지 말고, 어떤 문제를 해결하려는지와 다른 선택지 대비 장단점을 함께 설명해야 한다.');
SET @gce1_1 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@gce1_1, (SELECT id FROM tag WHERE name = 'OAuth 2.0')),
(@gce1_1, (SELECT id FROM tag WHERE name = 'OIDC')),
(@gce1_1, (SELECT id FROM tag WHERE name = 'JWT'));
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('OAuth 2.0의 적용 판단', '실무에서 OAuth 2.0을 적용할 때 확인해야 할 조건과 주의점을 설명하시오.', 'ESSAY', 'MEDIUM', 'GENERAL_CS',
 '사용자 비밀번호를 제3자 앱에 주지 않고 권한 부여 서버가 발급한 액세스 토큰으로 보호 자원 접근을 위임하는 프로토콜이다. 따라서 적용 전에는 요구 사항, 데이터 또는 트래픽 규모, 실패 시 영향, 운영 복잡도를 확인해야 한다. 이 개념을 만능 해법으로 쓰지 말고 측정과 검증을 통해 적합성을 판단한다.');
SET @gce1_2 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@gce1_2, (SELECT id FROM tag WHERE name = 'OAuth 2.0')),
(@gce1_2, (SELECT id FROM tag WHERE name = 'OIDC')),
(@gce1_2, (SELECT id FROM tag WHERE name = 'JWT'));
