SET @gce6_1 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@gce6_1, (SELECT id FROM tag WHERE name = 'SQL 인젝션')),
(@gce6_1, (SELECT id FROM tag WHERE name = '접근 제어와 권한 모델'));
