 '현실적인 동시 요청과 데이터 조건에서 지연 시간·처리량·오류율·자원 사용량을 측정해 병목을 찾는 활동이다. 따라서 적용 전에는 요구 사항, 데이터 또는 트래픽 규모, 실패 시 영향, 운영 복잡도를 확인해야 한다. 이 개념을 만능 해법으로 쓰지 말고 측정과 검증을 통해 적합성을 판단한다.');
SET @gce22_2 = LAST_INSERT_ID();
INSERT INTO question_tag (question_id, tag_id) VALUES
(@gce22_2, (SELECT id FROM tag WHERE name = '부하 테스트와 성능 측정')),
(@gce22_2, (SELECT id FROM tag WHERE name = '확장성과 스케일 아웃'));
INSERT INTO question (title, content, type, difficulty, category, explanation) VALUES
('세션 클러스터링의 원리와 목적', '세션 클러스터링의 핵심 원리와 해결하려는 문제를 설명하시오.', 'ESSAY', 'MEDIUM', 'GENERAL_CS',
 '여러 서버 환경에서 세션을 공유 저장소에 두거나 복제·고정 세션으로 관리해 어떤 서버로 가도 로그인 상태를 유지하는 방식이다. 면접 답변에서는 이 정의만 나열하지 말고, 어떤 문제를 해결하려는지와 다른 선택지 대비 장단점을 함께 설명해야 한다.');
